#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5a
#define MLX90614_TOBJ1 0x07

int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read temperature from MLX90614
float read_temperature() {
    unsigned char buf[3];
    int ret;

    buf[0] = MLX90614_TOBJ1;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        return -1.0;
    }

    ret = read(i2c_fd, buf, 3);
    if (ret != 3) {
        perror("Failed to read from I2C device");
        return -1.0;
    }

    unsigned int raw_temp = (buf[1] << 8) | buf[0];
    return (float)raw_temp * 0.02 - 273.15;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        printf("Temperature: %.2f °C\n", temperature);
        sleep(5);
    }

    // Cleanup (should not reach here under normal execution due to the signal handler)
    close(i2c_fd);
    return 0;
}

