#define GPIO_PIN 4 // BCM GPIO 4

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec delay = {0, 100000000}; // 100ms

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "my_program", 0); // Initial value 0
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) set to output mode.  Initial value: %d\n", GPIO_PIN, gpiod_line_get_value(line));

    // Toggle GPIO line
    while (!terminate) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d (BCM) set to HIGH\n", GPIO_PIN);
        nanosleep(&delay, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d (BCM) set to LOW\n", GPIO_PIN);
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

