#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 200000      // 200ms timeout

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 because of the round trip
}

// Function to report the distance
void reportDistance(double distance) {
    if (distance < 0) {
        printf("Error: No object detected or timeout occurred.\n");
    } else if (distance > MAX_DISTANCE) {
        printf("Error: Object out of range (%.2f cm).\n", distance);
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse duration
        long pulse_duration = measurePulse();

        // Calculate the distance
        double distance = calculateDistance(pulse_duration);

        // Report the distance
        reportDistance(distance);

        // Wait for 60 seconds
        sleep(60);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define ADS1115_ADDR 0x28    // ADS1115 I2C address
#define CONFIG_REG 0x01      // Configuration register
#define CONVERSION_REG 0x00 // Conversion register
#define FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
int i2c_setup(const char *bus, int addr);
int ads1115_read(int fd, int channel);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// ADS1115 read function
int ads1115_read(int fd, int channel) {
    uint8_t config[3];
    int16_t raw_value;
    float voltage;

    // Configure the ADS1115 for single-ended mode, channel selection, and 4.096V range
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // Single-shot mode, AIN0, +/- 4.096V, 128 SPS
    config[2] = 0x83; // Disable comparator, non-latching, alert/ready pin low

    if (write(fd, config, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    config[0] = CONVERSION_REG;
    if (write(fd, config, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, config, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    raw_value = (config[0] << 8) | config[1];

    // Convert raw value to voltage
    voltage = (float)raw_value * FULL_SCALE_VOLTAGE / 32768.0;

    // Basic validity check: check if voltage is within reasonable bounds
    if (voltage < -5.0 || voltage > 5.0) {
        fprintf(stderr, "Invalid voltage reading: %.3f\n", voltage);
        return -1;
    }

    return (int)(voltage * 1000); // Return voltage in millivolts
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, ADS1115_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int reading = ads1115_read(i2c_fd, 0); // Read from channel 0
        if (reading != -1) {
            printf("Voltage: %d mV\n", reading);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    close(i2c_fd);
    fprintf(stderr, "I2C bus closed.\n");

    return EXIT_SUCCESS;
}

