#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define CYCLE_COUNT 3
#define CYCLE_DELAY_SEC 2

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    int cycle = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output.\n", GPIO_PIN);

    while (!terminate && cycle < CYCLE_COUNT) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("Cycle %d: GPIO %d set HIGH\n", cycle + 1, GPIO_PIN);
        sleep(CYCLE_DELAY_SEC);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("Cycle %d: GPIO %d set LOW\n", cycle + 1, GPIO_PIN);
        sleep(CYCLE_DELAY_SEC);

        cycle++;
    }

    // Cleanup
    ret = gpiod_line_set_value(line, 0); // Ensure it's low before exiting
    if (ret < 0) {
        perror("Error setting GPIO low during cleanup");
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int main() {
    int file;
    uint8_t config[3];
    int16_t reading;
    int ret;

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Configure ADS1115 for single-ended input A0, 4.096V, continuous conversion, 128 SPS
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // 0b11000010
    config[2] = 0x83; // 0b10000011

    // Write configuration
    ret = write(file, config, 3);
    if (ret != 3) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Read conversion register
    config[0] = CONVERSION_REG;
    ret = write(file, config, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Read two bytes from conversion register
    uint8_t data[2];
    ret = read(file, data, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        close(file);
        return 1;
    }

    // Combine bytes to form 16-bit reading
    reading = (data[0] << 8) | data[1];

    // Print reading
    printf("Reading: %d\n", reading);

    // Close I2C bus
    close(file);

    return 0;
}

