// Function to read a single byte from the I2C device
int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    unsigned char data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return data;
}

// Function to write a single byte to the I2C device
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read temperature from the SI7021
float read_temperature() {
    if (i2c_write_byte(i2c_fd, MEASURE_TEMP_HOLD, 0) != 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1000.0; // Indicate error
    }
    usleep(100000); // Wait for measurement (at least 100ms)
    int raw_temp = i2c_read_byte(i2c_fd, 0) | (i2c_read_byte(i2c_fd, 0) << 8);
    if (raw_temp == -1) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1000.0;
    }
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to read humidity from the SI7021
float read_humidity() {
    if (i2c_write_byte(i2c_fd, MEASURE_HUMID_HOLD, 0) != 0) {
        fprintf(stderr, "Error writing humidity measurement command\n");
        return -1000.0; // Indicate error
    }
    usleep(100000); // Wait for measurement (at least 100ms)
    int raw_humidity = i2c_read_byte(i2c_fd, 0) | (i2c_read_byte(i2c_fd, 0) << 8);
    if (raw_humidity == -1) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1000.0;
    }
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to validate temperature reading
int validate_temperature(float temp) {
    if (temp < -40.0 || temp > 125.0) {
        fprintf(stderr, "Invalid temperature reading: %.2f\n", temp);
        return 0;
    }
    return 1;
}

