#include <signal.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define ADS1115_ADDR 0x48     // ADS1115 I2C address
#define CONFIG_REG 0x01       // Configuration register address
#define CONVERSION_REG 0x00  // Conversion register address
#define FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define SAMPLE_INTERVAL 1       // Sample every 1 second

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful exit
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the ADS1115
int config_ads1115(int fd) {
    // Configuration register value:
    // - Single-shot mode (0x80)
    // - AIN0 single-ended (0x40)
    // - 4.096V range (0x03)
    // - 128 SPS (0x03)
    uint16_t config_value = 0x8043; //0b1000000001000011

    // Write the configuration value to the configuration register
    uint8_t config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = (config_value >> 8) & 0xFF; // MSB
    config_data[2] = config_value & 0xFF;        // LSB

    if (write(fd, config_data, 3) != 3) {
        perror("Error writing to configuration register");
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc(int fd) {
    uint8_t conversion_data[2];
    conversion_data[0] = CONVERSION_REG;

    if (write(fd, conversion_data, 1) != 1) {
        perror("Error writing to conversion register");
        return -1;
    }

    if (read(fd, conversion_data, 2) != 2) {
        perror("Error reading from conversion register");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (conversion_data[0] << 8) | conversion_data[1];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    return (float)adc_value * FULL_SCALE_VOLTAGE / 32768.0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus. Exiting.\n");
        return 1;
    }

    // Configure ADS1115
    if (config_ads1115(i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure ADS1115. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Read and print ADC values
    for (int i = 0; i < 3; i++) {
        int16_t adc_value = read_adc(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        float voltage = convert_to_voltage(adc_value);
        printf("Reading %d: ADC Value = %d, Voltage = %.3f V\n", i + 1, adc_value, voltage);
        sleep(SAMPLE_INTERVAL);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

