    for (i = 0; i < 6; i++) {
        if (gpiod_line_request_output(lines[i], "my_program", 0) < 0) {
            perror("Error requesting GPIO line as output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    for (i = 0; i < 6; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Set GPIO output
void set_gpio_output(int gpio, int value) {
    int i;
    for (i = 0; i < 6; i++) {
        if (gpio == GPIO_8 + i) {
            if (gpiod_line_set_value(lines[i], value) < 0) {
                perror("Error setting GPIO value");
            }
            return;
        }
    }
    fprintf(stderr, "Invalid GPIO number: %d\n", gpio);
}

// Report state
void report_state(void) {
    int i;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ", timestamp);
    for (i = 0; i < 6; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value for GPIO %d\n", GPIO_8 + i);
            return;
        }
        printf("GPIO %d: %d ", GPIO_8 + i, value);
    }
    printf("\n");
}

int main(void) {
    int i, cycle;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    for (cycle = 0; cycle < NUM_CYCLES && !terminate; cycle++) {
        // Set GPIO outputs
        for (i = 0; i < 6; i++) {
            set_gpio_output(GPIO_8 + i, (cycle >> i) & 1);
        }

        // Report state
        report_state();

        // Delay
        usleep(DELAY_US);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return EXIT_SUCCESS;
}

