#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
    char *chip;
} gpio_line_t;

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static gpio_line_t gpio_lines[3];

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %d\n", line->number, ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d value: %d\n", line->number, value);
        return -1;
    }
    return value;
}

// Function to report GPIO state
void report_gpio_state(int pin, int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] GPIO %d: %d\n", timestamp, pin, value);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    gpio_lines[0].chip = "gpiochip0";
    gpio_lines[0].pin = GPIO_2;
    gpio_lines[0].line = gpiod_chip_get_line(chip, GPIO_2);
    if (!gpio_lines[0].line) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpio_lines[1].chip = "gpiochip0";
    gpio_lines[1].pin = GPIO_3;
    gpio_lines[1].line = gpiod_chip_get_line(chip, GPIO_3);
    if (!gpio_lines[1].line) {
        perror("Error getting GPIO line 3");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpio_lines[2].chip = "gpiochip0";
    gpio_lines[2].pin = GPIO_5;
    gpio_lines[2].line = gpiod_chip_get_line(chip, GPIO_5);
    if (!gpio_lines[2].line) {
        perror("Error getting GPIO line 5");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    for (int i = 0; i < 3; i++) {
        int ret = gpiod_line_request(gpio_lines[i].line, &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d as output: %d\n", gpio_lines[i].pin, ret);
            // Release previously requested lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(gpio_lines[j].line);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set initial values and report
    int values[3] = {0, 1, 0};
    for (int i = 0; i < 3; i++) {
        if (set_gpio_value(gpio_lines[i].line, values[i]) != 0) {
            // Release previously set lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(gpio_lines[j].line);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        report_gpio_state(gpio_lines[i].pin, values[i]);
    }

    // Keep the program running until a signal is received
    while (keep_running) {
        sleep(1);
    }

    // Release GPIO lines
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(gpio_lines[i].line);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

