#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        int start = gpioTick();
        while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start) < 50000) {}
        int echo_start = gpioTick();

        while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - echo_start) < 50000) {}
        int echo_end = gpioTick();

        int pulse_width = echo_end - echo_start;

        if (pulse_width < 0 || pulse_width > 50000) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            continue;
        }

        float distance = pulse_width / 2.0 / 29.1;

        printf("Distance: %.2f cm\n", distance);

        gpioDelay(1000); // 1 second delay
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

