#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define MAX_RETRIES 3

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    int retries = 0;
    struct timespec delay = {0, 100000000}; // 100ms

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initial state check
    int current_state = gpiod_line_get_value(line);
    if (current_state < 0) {
        perror("Error reading GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Initial GPIO state: %d\n", current_state);

    // Set GPIO to HIGH
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Wait for a short period
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    nanosleep(&sleep_time, NULL);

    // Read GPIO state
    current_state = gpiod_line_get_value(line);
    if (current_state < 0) {
        perror("Error reading GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO state after setting HIGH: %d\n", current_state);

    // Set GPIO to LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Wait for a short period
    nanosleep(&sleep_time, NULL);

    // Read GPIO state
    current_state = gpiod_line_get_value(line);
    if (current_state < 0) {
        perror("Error reading GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO state after setting LOW: %d\n", current_state);

    // Release GPIO line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

