        printf("GPIO %d set to 1\n", GPIO_PIN);
        fflush(stdout);
        sleep(2);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        fflush(stdout);
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

