#define GPIO_3 3
#define NUM_CYCLES 3

static struct gpiod_chip *chip;
static struct gpiod_line *line2, *line3;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int i, ret;
    const char *chipname = GPIO_CHIP;

    /* Register signal handler for SIGINT (Ctrl+C) */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'.\n", chipname);
        return EXIT_FAILURE;
    }

    /* Get GPIO lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", GPIO_2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error: Could not get GPIO line %d.\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO lines for output */
    ret = gpiod_line_request_output(line2, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output.\n", GPIO_2);
        gpiod_line_release(line3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d as output.\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    for (i = 0; i < NUM_CYCLES && !terminate; i++) {
        printf("Cycle %d:\n", i + 1);

        /* Set GPIO 2 HIGH */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d HIGH.\n", GPIO_2);
            break;
        }
        printf("  GPIO %d set HIGH\n", GPIO_2);
        usleep(500000); // 500ms

        /* Set GPIO 3 HIGH */
        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d HIGH.\n", GPIO_3);
            break;
        }
        printf("  GPIO %d set HIGH\n", GPIO_3);
        usleep(500000); // 500ms

        /* Set GPIO 2 LOW */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d LOW.\n", GPIO_2);
            break;
        }
        printf("  GPIO %d set LOW\n", GPIO_2);
        usleep(500000); // 500ms

        /* Set GPIO 3 LOW */
        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d LOW.\n", GPIO_3);
            break;
        }
        printf("  GPIO %d set LOW\n", GPIO_3);
        usleep(500000); // 500ms
    }

    /* Release GPIO lines */
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return terminate ? EXIT_FAILURE : EXIT_SUCCESS;
}

