#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line_4, *line_17, *line_22, *line_27;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line_4, struct gpiod_line *line_17, struct gpiod_line *line_22, struct gpiod_line *line_27);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line_4, line_17, line_22, line_27);
    exit(0);
}

// Function to set up a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio, struct gpiod_line **line) {
    struct gpiod_line_request_config config;
    int ret;

    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", gpio);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for line\n");
        return -1;
    }
    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line_4, struct gpiod_line *line_17, struct gpiod_line *line_22, struct gpiod_line *line_27) {
    if (line_4) {
        gpiod_line_release(line_4);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (line_22) {
        gpiod_line_release(line_22);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Set up GPIO lines
    if (setup_gpio(chip, GPIO_4, &line_4) < 0) {
        cleanup_gpio(chip, NULL, NULL, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_17, &line_17) < 0) {
        cleanup_gpio(chip, line_4, NULL, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_22, &line_22) < 0) {
        cleanup_gpio(chip, line_4, line_17, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_27, &line_27) < 0) {
        cleanup_gpio(chip, line_4, line_17, line_22, NULL);
        return 1;
    }

    // Set GPIO output values
    if (set_gpio_output(line_4, 1) < 0) {
        cleanup_gpio(chip, line_4, line_17, line_22, line_27);
        return 1;
    }
    if (set_gpio_output(line_17, 0) < 0) {
        cleanup_gpio(chip, line_4, line_17, line_22, line_27);
        return 1;
    }
    if (set_gpio_output(line_22, 1) < 0) {
        cleanup_gpio(chip, line_4, line_17, line_22, line_27);
        return 1;
    }
    if (set_gpio_output(line_27, 0) < 0) {
        cleanup_gpio(chip, line_4, line_17, line_22, line_27);
        return 1;
    }

    // Report the state applied to standard output
    printf("GPIO 4: %d\n", gpiod_line_get_value(line_4));
    printf("GPIO 17: %d\n", gpiod_line_get_value(line_17));
    printf("GPIO 22: %d\n", gpiod_line_get_value(line_22));
    printf("GPIO 27: %d\n", gpiod_line_get_value(line_27));

    // Clean up GPIO resources before exiting
    cleanup_gpio(chip, line_4, line_17, line_22, line_27);

    return 0;
}

