int gpio_pins[] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_27};
int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *lines[5]; // Array to hold the line objects

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close the GPIO lines
    for (int i = 0; i < num_pins; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines
    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            perror("Error getting GPIO line");
            // Clean up already opened lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the GPIO line for output
        if (gpiod_line_request_output(lines[i], "my_program", 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Clean up already opened lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Toggle the GPIO pins
        for (int i = 0; i < num_pins; i++) {
            int current_value = gpiod_line_get_value(lines[i]);
            int new_value = (current_value == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], new_value) < 0) {
                perror("Error setting GPIO line value");
                // Clean up already opened lines
                for (int j = 0; j < num_pins; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }
            printf("GPIO %d: %d\n", gpio_pins[i], new_value);
        }

        // Wait for 0.05 seconds
        usleep(50000); // 50000 microseconds = 0.05 seconds
    }

    return 0;
}

