#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00

int main() {
    int file;
    char filename[20];
    int i2c_address = OPT3001_ADDR;
    uint16_t config_value = 0x0190; // Continuous mode, 100ms conversion time
    uint16_t result;
    float voltage;
    int status;

    // Open I2C device
    snprintf(filename, 19, "/dev/i2c-1");
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Write configuration register
    uint8_t config_data[3];
    config_data[0] = CONFIG_REG;
    config_data[1] = (config_value >> 8) & 0xFF;
    config_data[2] = config_value & 0xFF;

    if (write(file, config_data, 3) != 3) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    // Read result register
    uint8_t result_data[2];
    result_data[0] = RESULT_REG;

    if (write(file, result_data, 1) != 1) {
        perror("Failed to write to I2C device");
        close(file);
        return 1;
    }

    if (read(file, result_data, 2) != 2) {
        perror("Failed to read from I2C device");
        close(file);
        return 1;
    }

    result = (result_data[0] << 8) | result_data[1];

    // Extract exponent and result
    int exponent = (result >> 12) & 0x0F;
    int result_val = result & 0x0FFF;

    // Calculate voltage
    voltage = 0.01 * (1 << exponent) * result_val;

    printf("Voltage: %.2f V\n", voltage);

    close(file);
    return 0;
}

