    cleanup_gpio(chip, line_2, line_3);
    exit(0);
}

// Function to setup GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request(*line, "my_program", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        fprintf(stderr, "Error: Could not request line for GPIO %d as output\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value)) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get GPIO input
int get_gpio_input(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line_2, struct gpiod_line *line_3) {
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
        gpiod_line_release(line_3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

