    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 1 deciseconds (0.1 seconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0;
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the string
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[256];
    struct timespec start, end;
    long elapsed_ms;

    printf("Reading from UART. Press Ctrl+C to exit.\n");

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read == 0) {
            // Timeout occurred
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
            if (elapsed_ms >= TIMEOUT_MS) {
                fprintf(stderr, "Timeout reading from UART.\n");
                keep_running = 0; // Exit the loop after timeout
            }
        } else {
            // Error occurred
            keep_running = 0;
        }
    }

    close(uart_fd);
    printf("UART communication stopped.\n");
    return EXIT_SUCCESS;
}

