    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, defaults to 255)
    gpioSetPWMrange(PWM_GPIO, 1000);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 10;

    while (!terminate) {
        // Set PWM duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the current duty cycle
        printf("PWM Duty Cycle: %d\n", duty_cycle);

        // Increment duty cycle
        duty_cycle += increment;

        // Reverse direction if reaching the maximum or minimum
        if (duty_cycle >= 1000) {
            increment = -10;
        } else if (duty_cycle <= 0) {
            increment = 10;
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM and release GPIO
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input (safer)

    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

