    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && device_count < MAX_DEVICES) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            // Found a DS18B20 device
            char device_path[100];
            snprintf(device_path, sizeof(device_path), "%s/%s", W1_DEVICES_DIR, ent->d_name);

            // Check if the device is present by reading its w1_slave file
            char slave_path[120];
            snprintf(slave_path, sizeof(slave_path), "%s/w1_slave", device_path);

            FILE *slave_file = fopen(slave_path, "r");
            if (slave_file == NULL) {
                // Device might not be ready yet or doesn't exist
                continue;
