            fclose(slave_file);

            // Store the device information
            devices[device_count].gpio = ent->d_name[3] - '0' + 10; // Convert the 4th character to GPIO number
            strncpy(devices[device_count].device_id, ent->d_name, sizeof(devices[device_count].device_id) - 1);
            devices[device_count].device_id[sizeof(devices[device_count].device_id) - 1] = '\0'; // Ensure null termination

