float read_temperature(const char *device_id) {
    char device_path[100];
    snprintf(device_path, sizeof(device_path), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    FILE *w1_slave_file = fopen(device_path, "r");
    if (w1_slave_file == NULL) {
        fprintf(stderr, "Error opening w1_slave file for device %s: %s\n", device_id, strerror(errno));
        return -1000.0; // Indicate an error
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), w1_slave_file) == NULL || fgets(line2, sizeof(line2), w1_slave_file) == NULL) {
        fprintf(stderr, "Error reading w1_slave file for device %s: %s\n", device_id, strerror(errno));
        fclose(w1_slave_file);
        return -1000.0; // Indicate an error
    }

    fclose(w1_slave_file);

    // Check for CRC error
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1000.0; // Indicate an error
    }

    // Extract temperature from line2
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
