int read_temperature(int fd) {
    unsigned char buf[3];
    int result;

    // Send the "Measure Temperature" command (0xE3)
    buf[0] = 0xE3;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for the measurement to complete (at least 50ms)
    usleep(50000);

    // Read the temperature data (2 bytes) and CRC (1 byte)
    if (read(fd, buf, 3) != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Combine the two data bytes into a 16-bit value
    int raw_temperature = (buf[0] << 8) | buf[1];

    // Apply the conversion formula from the datasheet
    float temperature = -46.85 + 175.72 * (raw_temperature / 65536.0);

    return (int)(temperature * 100); // Return temperature in hundredths of a degree
}

