        return -1;
    }
    return 0;
}

// Function to read acceleration data from ADXL345
int read_adxl345_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_register(fd, ADXL345_DATAX0);
    x1 = i2c_read_register(fd, ADXL345_DATAX1);
    y0 = i2c_read_register(fd, ADXL345_DATAY0);
    y1 = i2c_read_register(fd, ADXL345_DATAY1);
    z0 = i2c_read_register(fd, ADXL345_DATAZ0);
    z1 = i2c_read_register(fd, ADXL345_DATAZ1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x1 << 8) | x0);
    *y = (int16_t)((y1 << 8) | y0);
    *z = (int16_t)((z1 << 8) | z0);

    return 0; // Indicate success
}

