    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        perror("Error getting GPIO line 18");
        gpiod_chip_close(chip);
        if(line) gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        if(line) gpiod_line_release(line);
        if(line_18) gpiod_line_release(line_18);
        return EXIT_FAILURE;
    }

    memset(&config_18, 0, sizeof(config_18));
    config_18.consumer = "my_program_18";
    config_18.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config_18.flags = 0;

    ret = gpiod_line_request(line_18, &config_18, 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 for output");
        gpiod_chip_close(chip);
        if(line) gpiod_line_release(line);
        if(line_18) gpiod_line_release(line_18);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Toggle GPIO state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            perror("Error getting GPIO value");
            break;
        }

        ret = gpiod_line_set_value(line, !current_value);
        if (ret < 0) {
            perror("Error setting GPIO value");
