        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN, !current_value, GPIO_PIN_18, !current_value);

        // Sleep for 1 second
        nanosleep(&sleep_time, &remaining_time);
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_line_release(line_18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

