#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable register values
#define TCS34725_ENABLE_AIEN 0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN 0x08   // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN 0x02   // ALS Enable
#define TCS34725_ENABLE_PON 0x01   // Power on

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to read a 16-bit word from the I2C device
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return (buf[1] << 8) | buf[0];
}

// Function to write a byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable power and ALS
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        fprintf(stderr, "Error enabling power.\n");
        return -1;
    }
    usleep(3000); // Wait for power-on
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error enabling ALS.\n");
        return -1;
    }

    // Set integration time (ATIME) - Adjust as needed
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xD5) < 0) { // 101ms integration time
        fprintf(stderr, "Error setting integration time.\n");
        return -1;
    }

    // Set gain (AGAIN) - Adjust as needed
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x01) < 0) { // Gain = 4x
        fprintf(stderr, "Error setting gain.\n");
        return -1;
    }

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retries = 3; // Number of retries for I2C initialization

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        int c, r, g, b;

        // Read color data
        c = i2c_read_word(i2c_fd, TCS34725_CDATA);
        r = i2c_read_word(i2c_fd, TCS34725_RDATA);
        g = i2c_read_word(i2c_fd, TCS34725_GDATA);
        b = i2c_read_word(i2c_fd, TCS34725_BDATA);

        if (c < 0 || r < 0 || g < 0 || b < 0) {
            fprintf(stderr, "Error reading color data.\n");
        } else {
            printf("C: %d, R: %d, G: %d, B: %d\n", c, r, g, b);
        }

        usleep(200000); // 0.2 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

