    }

    if (gpiod_line_request(*line, "my_program", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        fprintf(stderr, "Error: Could not request line for GPIO %d\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value)) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line18, struct gpiod_line *line21, struct gpiod_line *line22) {
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line21) {
        gpiod_line_release(line21);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_18, &line18) != 0) {
        cleanup_gpio(chip, NULL, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_21, &line21) != 0) {
        cleanup_gpio(chip, line18, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_22, &line22) != 0) {
        cleanup_gpio(chip, line18, line21, NULL);
        return 1;
    }

    // Set GPIO output values
    if (set_gpio_output(line18, 1) != 0) {
        cleanup_gpio(chip, line18, line21, line22);
        return 1;
    }
    if (set_gpio_output(line21, 0) != 0) {
        cleanup_gpio(chip, line18, line21, line22);
        return 1;
    }
    if (set_gpio_output(line22, 1) != 0) {
        cleanup_gpio(chip, line18, line21, line22);
        return 1;
    }

    // Get and print GPIO output values
    int value18 = get_gpio_output(line18);
    int value21 = get_gpio_output(line21);
    int value22 = get_gpio_output(line22);

    if (value18 >= 0 && value21 >= 0 && value22 >= 0) {
        printf("GPIO 18: %d\n", value18);
        printf("GPIO 21: %d\n", value21);
        printf("GPIO 22: %d\n", value22);
    } else {
        fprintf(stderr, "Error: Could not read GPIO values\n");
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio(chip, line18, line21, line22);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    unsigned int n_buffers;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    FILE *fp = fopen("capture.yuyv", "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, buf.bytesused, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    munmap(buffer, buf.length);
    close(fd);

    printf("Image captured and saved to capture.yuyv\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
