#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 22
#define GPIO_PIN2 27

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line2;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 10000000}; // 0.01 seconds
    int value = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!line2) {
        perror("Error getting GPIO line2");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        ret = gpiod_line_set_value(line2, !value);
        if (ret < 0) {
            perror("Error setting GPIO line2 value");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN, value, GPIO_PIN2, !value);
        fflush(stdout);

        value = !value;
        nanosleep(&sleep_time, NULL);
    }

    printf("Cleaning up...\n");
    gpiod_line_set_value(line, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
