#include <errno.h>

// SSD1306 I2C address
#define SSD1306_I2C_ADDR 0x3C

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Screen dimensions
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a command to the SSD1306
int ssd1306_command(int fd, unsigned char command) {
    unsigned char buffer[2];
    buffer[0] = 0x00; // Control byte for command
    buffer[1] = command;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }
    return 0;
}

// Function to write data to the SSD1306
int ssd1306_data(int fd, unsigned char data) {
    unsigned char buffer[2];
    buffer[0] = 0x40; // Control byte for data
    buffer[1] = data;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to initialize the SSD1306
int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) != 0) return -1; // Display off
    if (ssd1306_command(fd, 0xD5) != 0) return -1; // Set display clock divide ratio/oscillator frequency
    if (ssd1306_command(fd, 0x80) != 0) return -1; // --ratio
    if (ssd1306_command(fd, 0xA8) != 0) return -1; // Set multiplex ratio
    if (ssd1306_command(fd, 0x3F) != 0) return -1; // --ratio
    if (ssd1306_command(fd, 0xD3) != 0) return -1; // Set display offset
    if (ssd1306_command(fd, 0x00) != 0) return -1; // --offset
    if (ssd1306_command(fd, 0x40 | 0x00) != 0) return -1; // Set start line address
    if (ssd1306_command(fd, 0x8D) != 0) return -1; // Charge pump setting
    if (ssd1306_command(fd, 0x14) != 0) return -1; // --enable
    if (ssd1306_command(fd, 0x20) != 0) return -1; // Set memory addressing mode
    if (ssd1306_command(fd, 0x00) != 0) return -1; // --mode
    if (ssd1306_command(fd, 0xA1) != 0) return -1; // Set segment re-map
    if (ssd1306_command(fd, 0xC8) != 0) return -1; // Set COM output scan direction
    if (ssd1306_command(fd, 0xDA) != 0) return -1; // Set COM pins hardware configuration
    if (ssd1306_command(fd, 0x12) != 0) return -1; // --config
    if (ssd1306_command(fd, 0x81) != 0) return -1; // Set contrast control
    if (ssd1306_command(fd, 0xCF) != 0) return -1; // --contrast
    if (ssd1306_command(fd, 0xD9) != 0) return -1; // Set pre-charge period
    if (ssd1306_command(fd, 0xF1) != 0) return -1; // --period
    if (ssd1306_command(fd, 0xDB) != 0) return -1; // Set VCOM deselect level
    if (ssd1306_command(fd, 0x40) != 0) return -1; // --level
    if (ssd1306_command(fd, 0xA4) != 0) return -1; // Set entire display on/off
    if (ssd1306_command(fd, 0xA6) != 0) return -1; // Set normal/inverse display
    if (ssd1306_command(fd, 0xAF) != 0) return -1; // Display on

    return 0;
}

// Function to clear the display
int ssd1306_clear(int fd) {
    for (int i = 0; i < SCREEN_WIDTH * SCREEN_HEIGHT / 8; i++) {
        if (ssd1306_data(fd, 0x00) != 0) return -1;
    }
    return 0;
}

// Function to display a string at a given position
int ssd1306_display_string(int fd, int x, int y, const char *str) {
    // Simple character mapping (ASCII 32-126)
    // This is a placeholder; a real implementation would use a font
    // and calculate the pixel data for each character.
    // For simplicity, we'll just display a single pixel for each character.
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (ssd1306_data(fd, 0x01) != 0) return -1; // Display a single pixel
        // In a real implementation, you would calculate the correct pixel data
        // based on the character and its position.
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the SSD1306
    if (ssd1306_init(i2c_fd) != 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Clear the display
        if (ssd1306_clear(i2c_fd) != 0) {
            fprintf(stderr, "Failed to clear display\n");
        }

        // Display some text
        if (ssd1306_display_string(i2c_fd, 0, 0, "Hello, World!") != 0) {
            fprintf(stderr, "Failed to display string\n");
        }

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // The program should never reach here due to the infinite loop
    close(i2c_fd);
    return 0;
}

