// BME280 Registers
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// I2C Address
#define BME280_I2C_ADDR 0x76

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int bme280_init();
int bme280_read_calibration_data();
int bme280_read_data(int32_t *temperature, int32_t *pressure, int32_t *humidity);
void bme280_convert_data(int32_t raw_temp, int32_t raw_pressure, int32_t raw_humidity, float *temperature, float *pressure, float *humidity);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize the BME280 sensor
int bme280_init() {
    uint8_t id;

    // Check the device ID
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (read(i2c_fd, &id, 1) != 1) {
        perror("Error: Could not read device ID");
        return -1;
    }

    if (id != 0x60) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", id);
        return -1;
    }

    // Reset the device
    uint8_t reset_cmd = 0xB6;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Error: Could not write reset command");
        return -1;
    }
    usleep(10000); // Wait for the reset to complete

    // Set humidity oversampling to 1x
    uint8_t ctrl_hum = 0x01;
    if (write(i2c_fd, &ctrl_hum, 1) != 1) {
        perror("Error: Could not write humidity control register");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    uint8_t ctrl_meas = (0x01 << 5) | (0x01 << 2) | 0x03; // osrs_t = 1, osrs_p = 1, normal mode
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Error: Could not write control measurement register");
        return -1;
    }

    // Set the config register (t_sb = 0.5ms, filter = off)
    uint8_t config = 0x00;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Error: Could not write config register");
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int bme280_read_calibration_data() {
    uint8_t buffer[26];
    if (read(i2c_fd, buffer, 26) != 26) {
        perror("Error: Could not read calibration data (first 26 bytes)");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (read(i2c_fd, buffer_h, 7) != 7) {
        perror("Error: Could not read calibration data (last 7 bytes)");
        return -1;
    }

    calib.dig_H2 = (int16_t)buffer_h[0] | ((int16_t)buffer_h[1] << 8);
    calib.dig_H3 = buffer_h[2];
    calib.dig_H4 = ((int16_t)buffer_h[3] << 4) | (buffer_h[4] & 0x0F);
    calib.dig_H5 = ((int16_t)buffer_h[5] << 4) | ((buffer_h[4] >> 4) & 0x0F);
    calib.dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// Read raw temperature, pressure, and humidity data from the sensor
int bme280_read_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];

    if (read(i2c_fd, buffer, 8) != 8) {
        perror("Error: Could not read data");
        return -1;
    }

    *pressure = (int32_t)buffer[0] << 12 | (int32_t)buffer[1] << 4 | (int32_t)buffer[2] >> 4;
