#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define ADS1115_ADDR 0x48     // ADS1115 I2C address
#define CONFIG_REG 0x01       // Configuration register address
#define CONVERSION_REG 0x00  // Conversion register address
#define FULL_SCALE_VOLTAGE 4.096 // Full-scale voltage (V)
#define SLEEP_DURATION 0.2      // Sleep duration (seconds)

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the I2C device
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the I2C device
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to initialize the ADS1115
int ads1115_init(int fd) {
    // Configuration register settings:
    // - Single-shot mode
    // - AIN0 single-ended input
    // - +/- 4.096V range
    // - 128 SPS
    // - Disable comparator
    uint16_t config = 0x4003; //0b0100000000000011

    if (i2c_write_word(fd, CONFIG_REG, config) != 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the ADC value from the ADS1115
int ads1115_read_adc(int fd, float *voltage) {
    uint16_t conversion;

    if (i2c_read_word(fd, CONVERSION_REG, &conversion) != 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    // Sign extend if negative
    int16_t signed_conversion = (int16_t)((conversion << 8) >> 8);

    // Convert to voltage
    *voltage = (float)signed_conversion * FULL_SCALE_VOLTAGE / 32768.0;

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float voltage;

        if (ads1115_read_adc(i2c_fd, &voltage) == 0) {
            printf("Voltage: %.3f V\n", voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(SLEEP_DURATION);
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    return 0;
}

