        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        sleep(30);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables for signal handling
static volatile int keep_running = 1;
static int i2c_fd = -1;

// Signal handler function
void int_handler(int dummy)
{
    keep_running = 0;
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return data;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    int x_h = i2c_read_reg(fd, ACCEL_XOUT_H);
    int x_l = i2c_read_reg(fd, ACCEL_XOUT_H + 1);
    int y_h = i2c_read_reg(fd, ACCEL_YOUT_H);
    int y_l = i2c_read_reg(fd, ACCEL_YOUT_H + 1);
    int z_h = i2c_read_reg(fd, ACCEL_ZOUT_H);
    int z_l = i2c_read_reg(fd, ACCEL_ZOUT_H + 1);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0; // Indicate success
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    int16_t accel_x, accel_y, accel_z;

    // Main loop
    while (keep_running) {
        if (read_accel_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }
        usleep(10000); // 0.01 seconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

