// Define the I2C address of the HD44780 display
#define I2C_ADDR 0x27

// Define the I2C bus (usually 1 on Raspberry Pi)
#define I2C_BUS "/dev/i2c-1"

// Define the display dimensions
#define DISPLAY_WIDTH 16
#define DISPLAY_HEIGHT 2

// Function prototypes
int i2c_setup(const char *bus, int addr);
void i2c_write_byte(int fd, unsigned char data);
void i2c_write_command(int fd, unsigned char command);
void i2c_write_data(int fd, unsigned char data);
void lcd_init(int fd);
void lcd_clear(int fd);
void lcd_set_cursor(int fd, int row, int col);
void lcd_print(int fd, const char *text);
void cleanup(int fd);
void signal_handler(int signum);

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        cleanup(i2c_fd);
        exit(0);
    }
}

// Function to initialize the I2C bus
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to the I2C bus
void i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C bus");
    }
}

// Function to write a command to the LCD
void i2c_write_command(int fd, unsigned char command) {
    unsigned char data_u, data_l;
    data_u = (command & 0xF0) | 0x0C; // En = 1, Rw = 0, Rs = 0
    data_l = ((command << 4) & 0xF0) | 0x0C; // En = 1, Rw = 0, Rs = 0

    i2c_write_byte(fd, data_u);
    usleep(1000); // Enable pulse width
    i2c_write_byte(fd, data_u & 0xF9); // Disable enable
    usleep(1000);

    i2c_write_byte(fd, data_l);
    usleep(1000); // Enable pulse width
    i2c_write_byte(fd, data_l & 0xF9); // Disable enable
    usleep(1000);
}

// Function to write data to the LCD
void i2c_write_data(int fd, unsigned char data) {
    unsigned char data_u, data_l;
    data_u = (data & 0xF0) | 0x0D; // En = 1, Rw = 0, Rs = 1
    data_l = ((data << 4) & 0xF0) | 0x0D; // En = 1, Rw = 0, Rs = 1

    i2c_write_byte(fd, data_u);
    usleep(1000); // Enable pulse width
    i2c_write_byte(fd, data_u & 0xF8); // Disable enable
    usleep(1000);

    i2c_write_byte(fd, data_l);
    usleep(1000); // Enable pulse width
    i2c_write_byte(fd, data_l & 0xF8); // Disable enable
    usleep(1000);
}

// Function to initialize the LCD
void lcd_init(int fd) {
    usleep(50000); // Wait for more than 4.1ms after power-on
    i2c_write_command(fd, 0x30); // Function set: 8-bit interface
    usleep(5000); // Wait for more than 4.1ms
    i2c_write_command(fd, 0x30); // Function set: 8-bit interface
    usleep(100); // Wait for more than 100us
    i2c_write_command(fd, 0x30); // Function set: 8-bit interface
    i2c_write_command(fd, 0x20); // Function set: 4-bit interface
    i2c_write_command(fd, 0x28); // Function set: 4-bit, 2 lines, 5x8 font
    i2c_write_command(fd, 0x08); // Display off
    i2c_write_command(fd, 0x01); // Clear display
    usleep(2000); // Wait for clear display to complete
    i2c_write_command(fd, 0x06); // Entry mode set: increment cursor, no shift
    i2c_write_command(fd, 0x0C); // Display on, cursor off, blink off
}

// Function to clear the LCD display
void lcd_clear(int fd) {
    i2c_write_command(fd, 0x01); // Clear display
    usleep(2000); // Wait for clear display to complete
}

// Function to set the cursor position
void lcd_set_cursor(int fd, int row, int col) {
    int address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    i2c_write_command(fd, 0x80 + address); // Set DDRAM address
}

// Function to print text to the LCD
void lcd_print(int fd, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        i2c_write_data(fd, text[i]);
    }
}

// Function to cleanup resources
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = i2c_setup(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize the LCD
    lcd_init(i2c_fd);

    // Main loop
    while (1) {
        // Clear the display
        lcd_clear(i2c_fd);

        // Print some text
        lcd_set_cursor(i2c_fd, 0, 0);
        lcd_print(i2c_fd, "Hello, World!");

        lcd_set_cursor(i2c_fd, 1, 0);
        lcd_print(i2c_fd, "Raspberry Pi");

        // Wait for 10 seconds
        sleep(10);
    }

    return 0;
}

