    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return (int16_t)((data[0] << 8) | data[1]);
}

