    if (write(i2c_fd, &wake_up_value, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        return 1;
    }

    // Read accelerometer data
    for (int i = 0; i < 100; i++) {
        int16_t accel_x = read_word(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_word(i2c_fd, ACCEL_YOUT_H);
        int16_t accel_z = read_word(i2c_fd, ACCEL_ZOUT_H);

        if (accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Error reading accelerometer data. Exiting.\n");
            close(i2c_fd);
            return 1;
        }

        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 14
#define GPIO_PIN_15 15
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line_15;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int value;
    int retries;
    struct timespec delay;
    char timestamp[30];

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_15 = gpiod_chip_get_line(chip, GPIO_PIN_15);
    if (!line_15) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN_15);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line_15);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_15, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_PIN_15);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line_15);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO output to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d to HIGH\n", GPIO_PIN);
            break;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Print state
        printf("%s GPIO %d: HIGH\n", timestamp, GPIO_PIN);

        // Set GPIO output to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d to LOW\n", GPIO_PIN);
            break;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Print state
        printf("%s GPIO %d: LOW\n", timestamp, GPIO_PIN);

        // Set GPIO output to HIGH
        ret = gpiod_line_set_value(line_15, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d to HIGH\n", GPIO_PIN_15);
            break;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Print state
        printf("%s GPIO %d: HIGH\n", timestamp, GPIO_PIN_15);

        // Set GPIO output to LOW
        ret = gpiod_line_set_value(line_15, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %d to LOW\n", GPIO_PIN_15);
            break;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL));

        // Print state
        printf("%s GPIO %d: LOW\n", timestamp, GPIO_PIN_15);

        // Wait 5 seconds
        delay.tv_sec = 5;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_line_release(line_15);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_TOPIC "sensor/temperature"
#define SENSOR_GPIO 4
#define READ_INTERVAL_MS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static MQTTClient client;
static char *broker_address = MQTT_BROKER_ADDRESS;
static char *topic = MQTT_TOPIC;

// Function prototypes
void signal_handler(int signal);
int read_sensor();
int validate_reading(int reading);
int publish_reading(int reading);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    int reading = gpioRead(SENSOR_GPIO);
    return reading;
}

// Validates the sensor reading
int validate_reading(int reading) {
    if (reading == 0 || reading == 1) {
        return 1; // Valid reading
    } else {
        return 0; // Invalid reading
    }
}

// Publishes the sensor reading to the MQTT broker
int publish_reading(int reading) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[10];

    snprintf(payload, sizeof(payload), "%d", reading);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return 0;
    }

    return 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int rc;
    int reading;
    int retries;
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    // Parse command-line arguments
    if (argc > 1) {
        broker_address = argv[1];
    }
    if (argc > 2) {
        topic = argv[2];
    }

    printf("Using MQTT broker: %s\n", broker_address);
    printf("Using MQTT topic: %s\n", topic);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize MQTT client
    MQTTClient_create(&client, broker_address, "sensor_client", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_setCallbacks(client, NULL, NULL, NULL, NULL);

    // Connect to MQTT broker
    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        cleanup();
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        retries = 0;
        do {
            reading = read_sensor();
            if (!validate_reading(reading)) {
                fprintf(stderr, "Invalid sensor reading: %d\n", reading);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            } else {
                break; // Valid reading, exit retry loop
            }
        } while (retries < MAX_RETRIES);

        if (validate_reading(reading)) {
            if (!publish_reading(reading)) {
                fprintf(stderr, "Failed to publish reading\n");
            }
        } else {
            fprintf(stderr, "Max retries reached, skipping reading\n");
        }

        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

