#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define STATE_PIN 27

// Define constants
#define MAX_DISTANCE 400.0  // Maximum valid distance in cm
#define MIN_DISTANCE 2.0    // Minimum valid distance in cm
#define TIMEOUT_US 25000     // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
long pulse_width();
float calculate_distance(long pulse_width);
void set_state_output(float distance);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for the echo pin to go high (start of pulse)
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (timeout++ > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Wait for the echo pin to go low (end of pulse)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (timeout++ > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * 0.0343 / 2.0;
}

// Function to set the state output based on distance
void set_state_output(float distance) {
    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        gpioWrite(STATE_PIN, 0); // Invalid distance
    } else {
        gpioWrite(STATE_PIN, 1); // Valid distance
    }
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(STATE_PIN, 0); // Set state pin low
    gpioTerminate();         // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(STATE_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance > 0) {
                printf("Distance: %.2f cm\n", distance);
                set_state_output(distance);
            } else {
                printf("Invalid distance reading.\n");
                gpioWrite(STATE_PIN, 0);
            }
        } else {
            printf("Timeout waiting for echo.\n");
            gpioWrite(STATE_PIN, 0);
        }

        gpioDelay(100); // Delay 100ms
    }

    cleanup(); // Clean up before exiting
    return 0;
}

