// Configuration
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_TOPIC "sensor/temperature"
#define SENSOR_GPIO 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_MS 1000 // Read interval in milliseconds

// Global variables
static volatile int running = 1;
MQTTClient client;
char *broker_address = MQTT_BROKER_ADDRESS;
char *topic = MQTT_TOPIC;

// Function prototypes
int read_sensor();
int publish_data(int sensor_value);
void signal_handler(int signal);
int connect_mqtt();
void disconnect_mqtt();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_GPIO);
}

// Function to publish data to MQTT broker
int publish_data(int sensor_value) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[10];

    snprintf(payload, sizeof(payload), "%d", sensor_value);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    return 0;
}

// Function to connect to the MQTT broker
int connect_mqtt() {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }

    printf("Connected to MQTT broker\n");
    return 0;
}

// Function to disconnect from the MQTT broker
void disconnect_mqtt() {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    printf("Disconnected from MQTT broker\n");
}

int main() {
    int rc;
    int sensor_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize MQTT client
    MQTTClient_create(&client, broker_address, "sensor_client", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (client == NULL) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    if (connect_mqtt() != 0) {
        gpioTerminate();
        MQTTClient_destroy(&client);
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor value
        sensor_value = read_sensor();

        // Publish data to MQTT broker
        if (publish_data(sensor_value) != 0) {
            fprintf(stderr, "Failed to publish data\n");
        }

        // Wait for the specified interval
        gpioDelay(READ_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Disconnect from MQTT broker
    disconnect_mqtt();

