#define PWM_DUTYCYCLE 500000 // 50% of 1000000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(PWM_GPIO, PWM_DUTYCYCLE);

    printf("PWM started on GPIO %d, Frequency: %d Hz, Duty Cycle: %d\n", PWM_GPIO, PWM_FREQUENCY, PWM_DUTYCYCLE);

    // Main loop
    while (!terminate) {
        // Report the state applied to standard output
        printf("PWM applied to GPIO %d, Frequency: %d Hz, Duty Cycle: %d\n", PWM_GPIO, PWM_FREQUENCY, PWM_DUTYCYCLE);
        fflush(stdout); // Ensure output is immediately flushed

        // Wait for 5 seconds
