#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (0.2 seconds)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance
float measureDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (timeout).\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (timeout).\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;
    if (diff_tick < 0) {
        diff_tick += 0xFFFFFFFF; // Handle tick rollover
    }

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measureDistance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        gpioDelay(200); // Wait 200 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

