#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_TOPIC "sensor/temperature"
#define SENSOR_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define MAX_SENSOR_READING 100.0
#define MIN_SENSOR_READING -20.0

// Global variables
static volatile int running = 1;
static MQTTClient client;
static char *broker_address = MQTT_BROKER_ADDRESS;
static char *topic = MQTT_TOPIC;

// Function prototypes
int read_sensor();
int validate_reading(float reading);
int publish_reading(float reading);
void signal_handler(int signal);
int connect_mqtt();
int disconnect_mqtt();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Read sensor value from GPIO
int read_sensor() {
    int reading = gpioRead(SENSOR_GPIO);
    if (reading < 0) {
        fprintf(stderr, "Error reading sensor: %d\n", reading);
        return -1;
    }
    return reading;
}

// Validate sensor reading
int validate_reading(float reading) {
    if (reading < MIN_SENSOR_READING || reading > MAX_SENSOR_READING) {
        fprintf(stderr, "Invalid reading: %.2f\n", reading);
        return 0; // Invalid
    }
    return 1; // Valid
}

// Publish reading to MQTT broker
int publish_reading(float reading) {
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    char payload[50];

    snprintf(payload, sizeof(payload), "%.2f", reading);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return 0;
    }

    printf("Published reading: %.2f\n", reading);
    return 1;
}

// Connect to MQTT broker
int connect_mqtt() {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return 0;
    }

    printf("Connected to MQTT broker\n");
    return 1;
}

// Disconnect from MQTT broker
int disconnect_mqtt() {
    int rc = MQTTClient_disconnect(client, 1000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to disconnect from MQTT broker, return code %d\n", rc);
        return 0;
    }

    printf("Disconnected from MQTT broker\n");
    return 1;
}

int main(int argc, char *argv[]) {
    int rc;
    int sensor_value;
    float temperature_reading;
    int retries = 0;

    // Parse command-line arguments
    if (argc > 1) {
        broker_address = argv[1];
    }
    if (argc > 2) {
        topic = argv[2];
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize MQTT client
    MQTTClient_create(&client, broker_address, "sensor_publisher", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (!client) {
        fprintf(stderr, "Failed to create MQTT client\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Connect to MQTT broker
    if (!connect_mqtt()) {
        gpioTerminate();
        MQTTClient_destroy(&client);
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor value
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert sensor value to temperature (example conversion)
        temperature_reading = (float)sensor_value * 0.5 + 20.0; // Example linear conversion

        // Validate reading
        if (!validate_reading(temperature_reading)) {
            fprintf(stderr, "Invalid reading, skipping publish\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Publish reading
        if (!publish_reading(temperature_reading)) {
            fprintf(stderr, "Failed to publish reading, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Exit after one successful publish
        break;
    }

    // Disconnect from MQTT broker
    disconnect_mqtt();

    // Destroy MQTT client
    MQTTClient_destroy(&client);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

