// Configuration
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define ADS1115_ADDR 0x48      // ADS1115 I2C address
#define CONFIG_REG 0x01        // Configuration register address
#define CONVERSION_REG 0x00   // Conversion register address
#define MQTT_TOPIC "sensor/ads1115/reading"
#define MQTT_CLIENT_ID "ads1115_publisher"
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
