// ADS1115 Configuration
#define CONFIG_DEFAULT 0x4003 // Single-shot mode, +/-4.096V, 128 SPS, AIN0 single-ended

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint16_t value);
int i2c_read_reg(int fd, uint8_t reg, uint16_t *value);
float read_ads1115(int fd);
void signal_handler(int sig);
int setup_i2c(int bus, int addr);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read from ADS1115
float read_ads1115(int fd) {
    uint16_t config = CONFIG_DEFAULT;
    uint16_t conversion;

    // Write configuration register
    if (i2c_write_reg(fd, CONFIG_REG, config) != 0) {
        fprintf(stderr, "Failed to write configuration register.\n");
        return NAN;
    }

    // Wait for conversion to complete (adjust delay as needed)
    usleep(10000); // 10ms

    // Read conversion register
    if (i2c_read_reg(fd, CONVERSION_REG, &conversion) != 0) {
        fprintf(stderr, "Failed to read conversion register.\n");
        return NAN;
    }

    // Convert to voltage (assuming +/-4.096V range)
    float voltage = (float)((int16_t)conversion) * 4.096 / 32768.0;

    return voltage;
}

// Setup I2C communication
int setup_i2c(int bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = setup_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C communication.\n");
        return 1;
    }

    // Main loop
    for (int i = 0; i < 10 && !terminate; i++) {
        float voltage = read_ads1115(i2c_fd);

