#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_PIN_18 18
#define POLL_INTERVAL_NS 50000000 // 0.05 seconds in nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line_18;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct timespec ts;
    int ret;
    int value;

    /* Set up signal handling */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line_18) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN_18);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line_18);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_18, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN_18, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line_18);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Toggle GPIO state */
        ret = gpiod_line_set_value(line, 1 - gpiod_line_get_value(line));
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN, strerror(-ret));
            break;
        }

        ret = gpiod_line_set_value(line_18, 1 - gpiod_line_get_value(line_18));
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_PIN_18, strerror(-ret));
            break;
        }

        /* Get current timestamp */
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        /* Print timestamp and GPIO state */
        printf("%ld.%09ld: GPIO %d state: %d\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN, gpiod_line_get_value(line));
        printf("%ld.%09ld: GPIO %d state: %d\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN_18, gpiod_line_get_value(line_18));

        /* Sleep for 0.05 seconds */
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_NS;
        nanosleep(&sleep_time, NULL);
    }

    /* Release GPIO line */
    gpiod_line_release(line);
    gpiod_line_release(line_18);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

