    terminate = 1;
}

int main() {
    int ret;
    int value;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to 1\n", GPIO_PIN);
        fflush(stdout);
        usleep(50000); // 0.05 seconds

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to 0\n", GPIO_PIN);
        fflush(stdout);
        usleep(50000); // 0.05 seconds
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <sys/ioctl.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    int uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    printf("Reading from UART %s...\n", UART_DEVICE);

    while (program_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, try again later
                usleep(100000); // 100ms
                continue;
            } else {
                perror("Error reading from UART");
                break;
            }
        } else {
            // Read returned 0, which can happen on EOF or other errors.
            break;
        }
    }

    close(uart_fd);
    printf("UART communication stopped.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from the I2C device
int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    unsigned char data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return data;
}

// Function to read two bytes from the I2C device
int i2c_read_word(int fd, unsigned char reg, short *value) {
    unsigned char data[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register. Check if device is present.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        short accel_x, accel_y, accel_z;

        // Read accelerometer data
        if (i2c_read_word(i2c_fd, ACCEL_XOUT_H, &accel_x) < 0 ||
            i2c_read_word(i2c_fd, ACCEL_YOUT_H, &accel_y) < 0 ||
            i2c_read_word(i2c_fd, ACCEL_ZOUT_H, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data. Check if device is present.\n");
            break; // Exit loop on error
        }

        // Print accelerometer data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// BMP280 Registers
#define BMP280_ADDR_76 0x76
#define BMP280_ADDR_77 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_RESET_REG 0xE0
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_DATA_REG 0xF7

// Calibration data registers
#define BMP280_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_16X 16

// Global variables
static int i2c_fd = -1;
static int bmp280_address = BMP280_ADDR_76; // Default address
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

// Signal handler for graceful shutdown
static void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the BMP280 sensor
int bmp280_init(int address) {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            retries--;
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        // Check the chip ID
        uint8_t chip_id;
        if (read(i2c_fd, &chip_id, 1) != 1) {
            fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        if (chip_id != 0x58) {
            fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        // Reset the sensor
        uint8_t reset_value = 0xB6;
        if (write(i2c_fd, &reset_value, 1) != 1) {
            fprintf(stderr, "Error writing reset value: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }
        usleep(10000); // Wait for the reset to complete

        // Configure the sensor (example settings)
        uint8_t config_value = (0x04 << 5) | (0x02 << 2) | 0x00; // t_sb = 0.5ms, filter = x4
        if (write(i2c_fd, &config_value, 1) != 1) {
            fprintf(stderr, "Error writing config value: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        uint8_t ctrl_meas_value = (BMP280_OVERSAMPLING_16X << 5) | (BMP280_OVERSAMPLING_16X << 2) | 0x03; // osrs_t = x16, osrs_p = x16, normal mode
        if (write(i2c_fd, &ctrl_meas_value, 1) != 1) {
            fprintf(stderr, "Error writing control measurement value: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Failed to initialize BMP280 after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read calibration data from the BMP280
int bmp280_read_calibration_data(int address, struct bmp280_calib_data *calib) {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            retries--;
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        uint8_t data[26];
        if (read(i2c_fd, data, 26) != 26) {
            fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
        calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
        calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
        calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
        calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
        calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
        calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
        calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
        calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
        calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
        calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
        calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

        close(i2c_fd);
        i2c_fd = -1;
        return 0; // Calibration data read successfully
    }

    fprintf(stderr, "Failed to read calibration data after multiple retries.\n");
    return -1; // Calibration data read failed
}

// Function to read temperature and pressure data from the BMP280
int bmp280_read_data(int address, float *temperature, float *pressure) {
    int retries = 3;
    while (retries > 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            retries--;
            sleep(1);
            continue;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            retries--;
            sleep(1);
            continue;
        }

        int32_t raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
        int32_t raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

        close(i2c_fd);
        i2c_fd = -1;

        // Dummy conversion (replace with actual BMP280 conversion formulas)
        *temperature = (float)raw_temperature / 100.0f;
        *pressure = (float)raw_pressure / 100.0f;

        return 0; // Data read successfully
    }

    fprintf(stderr, "Failed to read data after multiple retries.\n");
    return -1; // Data read failed
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "76") == 0) {
            bmp280_address = BMP280_ADDR_76;
        } else if (strcmp(argv[1], "77") == 0) {
            bmp280_address = BMP280_ADDR_77;
        } else {
            fprintf(stderr, "Invalid I2C address. Using default 0x76.\n");
        }
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the BMP280 sensor
    if (bmp280_init(bmp280_address) != 0) {
        fprintf(stderr, "Failed to initialize BMP280 sensor.\n");
        return EXIT_FAILURE;
    }

    // Read calibration data
    struct bmp280_calib_data calib;
    if (bmp280_read_calibration_data(bmp280_address, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        float temperature, pressure;

        // Read temperature and pressure data
        if (bmp280_read_data(bmp280_address, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read temperature and pressure data.\n");
        }

        sleep(5);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 4
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Apply PWM signal (50% duty cycle)
    result = gpioPWM(PWM_GPIO, PWM_RANGE / 2);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %d\n", result);
        gpioTerminate();
        return 1;
    }

    printf("PWM signal applied to GPIO %d (BCM), Frequency: %d Hz, Duty Cycle: 50%%\n", PWM_GPIO, PWM_FREQUENCY);

    // Wait for termination signal
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Stop PWM signal
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

// Define chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio5_line = NULL;
struct gpiod_line *gpio6_line = NULL;
struct gpiod_line *gpio13_line = NULL;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
void cleanup_gpio(struct gpiod_line *line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(gpio5_line);
    cleanup_gpio(gpio6_line);
    cleanup_gpio(gpio13_line);
    exit(0);
}

// Function to setup a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!(*line)) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request_output(*line, "my_program", 0) < 0) {
        fprintf(stderr, "Error: Could not request line for GPIO %d as output\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to cleanup a GPIO line
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_5, &gpio5_line) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_6, &gpio6_line) < 0) {
        cleanup_gpio(gpio5_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_13, &gpio13_line) < 0) {
        cleanup_gpio(gpio5_line);
        cleanup_gpio(gpio6_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 5
        if (set_gpio_output(gpio5_line, 1) < 0) {
            break;
        }
        printf("GPIO %d: 1\n", GPIO_5);
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio5_line, 0) < 0) {
            break;
        }
        printf("GPIO %d: 0\n", GPIO_5);
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 6
        if (set_gpio_output(gpio6_line, 1) < 0) {
            break;
        }
        printf("GPIO %d: 1\n", GPIO_6);
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio6_line, 0) < 0) {
            break;
        }
        printf("GPIO %d: 0\n", GPIO_6);
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 13
        if (set_gpio_output(gpio13_line, 1) < 0) {
            break;
        }
        printf("GPIO %d: 1\n", GPIO_13);
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio13_line, 0) < 0) {
            break;
        }
        printf("GPIO %d: 0\n", GPIO_13);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_gpio(gpio5_line);
    cleanup_gpio(gpio6_line);
    cleanup_gpio(gpio13_line);
    gpiod_chip_close(chip);

    return 0;
}

