void cleanup();
int read_sensor();
int publish_data(int sensor_value);
void log_message(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen("sensor_publisher.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT client
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        log_message("Failed to connect to MQTT broker");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_message("Initialization complete");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    log_message("Cleanup complete");
}

// Function to read sensor data
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_GPIO);
    return sensor_value;
}

// Function to publish data to MQTT broker
int publish_data(int sensor_value) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        log_message("Failed to publish message");
        return 1;
    }

    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Published: %s", payload);
    log_message(log_message_buffer);

    return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);
    fprintf(log_file, buf);
    fflush(log_file);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (publish_data(sensor_value) != 0) {
            log_message("Failed to publish data, retrying...");
            sleep(1); // Wait before retrying
        }
        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define PWM duty cycle (0-255)
#define PWM_DUTY_CYCLE 128

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM duty cycle for all pins
    gpioPWM(PWM_PIN_1, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_4, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_5, PWM_DUTY_CYCLE);

    // Print the state of the GPIO pins
    printf("PWM output on GPIO %d, %d, %d, %d, %d set to duty cycle %d\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5, PWM_DUTY_CYCLE);

    // Wait for termination signal
    while (!terminate)
    {
        gpioDelay(100); // Sleep for 100ms
    }

    // Stop PWM output and release GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);

    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to output
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_22, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(GPIO_17, 1000);
    gpioSetPWMfrequency(GPIO_22, 1000);
    gpioSetPWMfrequency(GPIO_27, 1000);

    // Set PWM range to 1000
    gpioSetPWMrange(GPIO_17, 1000);
    gpioSetPWMrange(GPIO_22, 1000);
    gpioSetPWMrange(GPIO_27, 1000);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 10;

    while (!terminate) {
        gpioPWM(GPIO_17, duty_cycle);
        gpioPWM(GPIO_22, duty_cycle);
        gpioPWM(GPIO_27, duty_cycle);

        printf("GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n", duty_cycle, duty_cycle, duty_cycle);

        duty_cycle += increment;

        if (duty_cycle >= 1000) {
            increment = -10;
        } else if (duty_cycle <= 0) {
            increment = 10;
        }

        gpioDelay(50000); // 50ms
    }

    // Stop PWM and release GPIOs
    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_22, 0);
    gpioPWM(GPIO_27, 0);

    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers;
unsigned int n_buffers;

int fd = -1; // File descriptor for the video device
int running = 1; // Flag to control the main loop

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int xioctl(int fh, int request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    FILE *fp;
    char filename[64];
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    signal(SIGINT, signal_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return 1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL /* start anywhere */,
                                        buf.length,
                                        PROT_READ | PROT_WRITE /* required */,
                                        MAP_SHARED /* recommended */,
                                        fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            return 1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            close(fd);
            return 1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return 1;
    }

    while (running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (EINTR == errno) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("select");
            break;
        }

        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            break;
        }

        snprintf(filename, sizeof(filename), "image_%ld.yuyv", time(NULL));
        fp = fopen(filename, "wb");
        if (!fp) {
            perror("fopen");
            break;
        }

        fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
        fclose(fp);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    /* After we're done, release the mapping for each buffer */
    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    close(fd);
    free(buffers);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    unsigned int n_buffers;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    FILE *fp = fopen("image.raw", "wb");
    if (fp == NULL) {
        perror("Error opening file");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, buf.bytesused, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    munmap(buffer, buf.length);
    close(fd);

    printf("Image captured and saved to image.raw\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN2 3
#define DELAY_MS 500

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line2;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec delay = {0, DELAY_MS * 1000000L}; // 0.5 seconds
    int state = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!line2) {
        perror("Error getting GPIO line2");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        ret = gpiod_line_set_value(line2, !state);
        if (ret < 0) {
            perror("Error setting GPIO line2 value");
            break;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN, state, GPIO_PIN2, !state);
        fflush(stdout);

        nanosleep(&delay, NULL);
        state = !state;
    }

    printf("Cleaning up...\n");
    gpiod_line_set_value(line, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_PIN2 27

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line2;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second
    struct timespec remaining_time;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!line2) {
        perror("Error getting GPIO line2");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return 1;
    }

    while (!terminate) {
        // Toggle GPIO 17
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        printf("GPIO 17 set to 1\n");
        nanosleep(&sleep_time, &remaining_time);
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        printf("GPIO 17 set to 0\n");
        nanosleep(&sleep_time, &remaining_time);

        // Toggle GPIO 27
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("Error setting GPIO 27 value");
            break;
        }
        printf("GPIO 27 set to 1\n");
        nanosleep(&sleep_time, &remaining_time);
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("Error setting GPIO 27 value");
            break;
        }
        printf("GPIO 27 set to 0\n");
        nanosleep(&sleep_time, &remaining_time);
    }

    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

