        gpiod_line_release(line_19);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_19, "my_program", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 19 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line_19);
