#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/serial.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B9600
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY 0 // 0=none, 1=odd, 2=even, 3=1.5, 4=1.0

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 9600 baud, 8 data bits, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_PORT);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    printf("UART port %s opened successfully.\n", UART_PORT);

    char buffer[256];
    ssize_t bytes_read;

    while (program_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EINTR) {
                // Timeout or interrupted by signal, continue looping
                continue;
            } else {
                perror("Error reading from UART");
                break;
            }
        } else {
            // No data received, sleep for a short time to avoid busy-waiting
            usleep(10000); // 10ms
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART port closed.\n");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
