struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_23, *line_24;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value);

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line);

// Function to report the state of GPIO pins
void report_state(int gpio_18_value, int gpio_23_value, int gpio_24_value);

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
