    if (!line_18 || !line_23 || !line_24) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_18, "my_program", 0) < 0 ||
        gpiod_line_request_output(line_23, "my_program", 0) < 0 ||
        gpiod_line_request_output(line_24, "my_program", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial values
    if (set_gpio_value(line_18, 1) < 0 ||
        set_gpio_value(line_23, 0) < 0 ||
