    report_state(1, 0, 1);

    // Release GPIO lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

