#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Apply PWM signal (50% duty cycle)
    gpioPWM(PWM_GPIO, PWM_RANGE / 2);

    // Report the state applied
    printf("PWM signal applied to GPIO %d (BCM), Frequency: %d Hz, Duty Cycle: 50%%\n", PWM_GPIO, PWM_FREQUENCY);

    // Keep the program running for a while
    sleep(5);

    // Stop PWM signal
    gpioPWM(PWM_GPIO, 0);

    // Release the GPIO
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input to release

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");

    return 0;
}

