#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30us

    gpioSetMode(gpio, PI_INPUT);

    int timings[MAX_TIMINGS];
    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpioRead(gpio) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 200) {
                fprintf(stderr, "DHT22 timeout error\n");
                return -1; // Timeout
            }
        }
        timings[i] = count;
    }

    for (i = 0; i < 40; i++) {
        pulse_count = timings[bit_count];
        bit_count++;
        if (pulse_count > 40) {
            fprintf(stderr, "DHT22 pulse width error\n");
            return -1; // Invalid pulse width
        }
        if (pulse_count > 20) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1; // Checksum error
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    result = read_dht22(DHT22_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 sensor\n");
    }

    gpioTerminate();
    return 0;
}

