#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <MQTTClient.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_TOPIC "home/sensor/adc_reading"
#define MQTT_CLIENT_ID "rpi_adc_publisher"
#define MQTT_QOS 1

// Global variables
int spi_fd;
MQTTClient client;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int read_adc(int channel);
int mqtt_connect();
int mqtt_publish(int adc_value);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// SPI initialization
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// MQTT connection
int mqtt_connect() {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        return -1;
    }

    printf("Connected to MQTT broker\n");
    return 0;
}

// MQTT publish
int mqtt_publish(int adc_value) {
    int rc;
    char payload[20];
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    snprintf(payload, sizeof(payload), "%d", adc_value);
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }

    printf("Published ADC value: %d\n", adc_value);
    return 0;
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (client != NULL) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize MQTT
    if (mqtt_connect() != 0) {
        fprintf(stderr, "MQTT connection failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            cleanup();
            return 1;
        }

        // Publish ADC value
        if (mqtt_publish(adc_value) != 0) {
            fprintf(stderr, "Failed to publish ADC value\n");
            cleanup();
            return 1;
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    unsigned int n_buffers;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    FILE *fp = fopen("capture.yuyv", "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    fwrite(buffer, 1, buf.bytesused, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        munmap(buffer, buf.length);
        close(fd);
        return 1;
    }

    munmap(buffer, buf.length);
    close(fd);

    printf("Image captured and saved as capture.yuyv\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
