// Define the GPIO pins to use for PWM
#define PWM_GPIO_1 4
#define PWM_GPIO_2 5
#define PWM_GPIO_3 6
#define PWM_GPIO_4 7
#define PWM_GPIO_5 8
#define PWM_GPIO_6 9

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define the PWM range (resolution)
#define PWM_RANGE 1000

// Define the PWM duty cycle values (0-100%)
#define DUTY_CYCLE_1 200
#define DUTY_CYCLE_2 400
#define DUTY_CYCLE_3 600
#define DUTY_CYCLE_4 800
#define DUTY_CYCLE_5 100
#define DUTY_CYCLE_6 300

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the PWM frequency for all GPIO pins
    gpioSetPWMfrequency(PWM_GPIO_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_GPIO_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_GPIO_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_GPIO_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_GPIO_6, PWM_FREQUENCY);

    // Set the PWM range for all GPIO pins
    gpioSetPWMrange(PWM_GPIO_1, PWM_RANGE);
    gpioSetPWMrange(PWM_GPIO_2, PWM_RANGE);
    gpioSetPWMrange(PWM_GPIO_3, PWM_RANGE);
    gpioSetPWMrange(PWM_GPIO_4, PWM_RANGE);
    gpioSetPWMrange(PWM_GPIO_5, PWM_RANGE);
    gpioSetPWMrange(PWM_GPIO_6, PWM_RANGE);

    // Set the PWM duty cycle for each GPIO pin
    gpioPWM(PWM_GPIO_1, DUTY_CYCLE_1);
    gpioPWM(PWM_GPIO_2, DUTY_CYCLE_2);
    gpioPWM(PWM_GPIO_3, DUTY_CYCLE_3);
    gpioPWM(PWM_GPIO_4, DUTY_CYCLE_4);
    gpioPWM(PWM_GPIO_5, DUTY_CYCLE_5);
    gpioPWM(PWM_GPIO_6, DUTY_CYCLE_6);

    // Print the PWM values to the console
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_1, DUTY_CYCLE_1);
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_2, DUTY_CYCLE_2);
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_3, DUTY_CYCLE_3);
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_4, DUTY_CYCLE_4);
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_5, DUTY_CYCLE_5);
    printf("GPIO %d: PWM = %d\n", PWM_GPIO_6, DUTY_CYCLE_6);

    // Wait for 5 seconds
    sleep(5);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define CYCLES 3

static struct gpiod_chip *chip;
static struct gpiod_line *line_17, *line_18;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int i, ret;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 100 * 1000 * 1000; // 100ms

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line_17 || !line_18) {
        perror("Error getting GPIO line");
        if(line_17) gpiod_line_release(line_17);
        if(line_18) gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_17, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_18, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 as output");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    for (i = 0; i < CYCLES && !terminate; i++) {
        // Cycle 1: 17 HIGH, 18 LOW
        ret = gpiod_line_set_value(line_17, 1);
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO 17 HIGH, GPIO 18 LOW\n", i + 1);
        nanosleep(&delay, NULL);

        // Cycle 2: 17 LOW, 18 HIGH
        ret = gpiod_line_set_value(line_17, 0);
        ret = gpiod_line_set_value(line_18, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO 17 LOW, GPIO 18 HIGH\n", i + 2);
        nanosleep(&delay, NULL);

        // Cycle 3: 17 LOW, 18 LOW
        ret = gpiod_line_set_value(line_17, 0);
        ret = gpiod_line_set_value(line_18, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO 17 LOW, GPIO 18 LOW\n", i + 3);
        nanosleep(&delay, NULL);
    }

    gpiod_line_release(line_17);
    gpiod_line_release(line_18);
    gpiod_chip_close(chip);

    return 0;
}

