#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// PCF8574 I2C address
#define PCF8574_ADDR 0x27

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C interface
int init_i2c() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to write a byte to the PCF8574
int write_pcf8574(unsigned char value) {
    if (write(i2c_fd, &value, 1) != 1) {
        perror("Error writing to PCF8574");
        return -1;
    }
    return 0;
}

// Function to display a number on the PCF8574 (0-9)
void display_number(int number) {
    if (number < 0 || number > 9) {
        fprintf(stderr, "Error: Number out of range (0-9)\n");
        return;
    }

    // Define segment patterns for digits 0-9 (adjust as needed for your display)
    unsigned char segments[10] = {
        0x3F, // 0
        0x06, // 1
        0x5B, // 2
        0x4F, // 3
        0x66, // 4
        0x6D, // 5
        0x7D, // 6
        0x07, // 7
        0x7F, // 8
        0x6F  // 9
    };

    if (write_pcf8574(segments[number]) != 0) {
        fprintf(stderr, "Error writing to display\n");
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format time as HH:MM
        char time_str[6]; // Enough space for "23:59\0"
        strftime(time_str, sizeof(time_str), "%H:%M", timeinfo);

        // Display the time on the PCF8574
        for (int i = 0; i < 5; i++) {
            display_number(time_str[i] - '0'); // Convert character to digit
            usleep(100000); // 100ms delay
        }

        sleep(1); // Update every second
    }

    return 0;
}

