#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_27 27

// Array of GPIO pins
int gpio_pins[] = {GPIO_4, GPIO_17, GPIO_22, GPIO_23, GPIO_24, GPIO_27};
int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *lines[6]; // Array to hold line pointers

// Function to set GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to get GPIO line value
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO value\n");
        return -1;
    }
    return value;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    // Set all GPIOs to input mode (safe state)
    for (int i = 0; i < num_pins; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_direction(lines[i], GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < num_pins; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            perror("Error getting GPIO line");
            // Clean up already acquired lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        int ret = gpiod_line_request_output(lines[i], "my_program", 0); // Initial value 0
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line for output: %d\n", ret);
            // Clean up already acquired lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Toggle GPIO values
        for (int i = 0; i < num_pins; i++) {
            int current_value = get_gpio_value(lines[i]);
            if (current_value < 0) {
                fprintf(stderr, "Error getting current GPIO value for pin %d\n", gpio_pins[i]);
                continue; // Continue to the next pin
            }
            int new_value = (current_value == 0) ? 1 : 0;
            if (set_gpio_value(lines[i], new_value) < 0) {
                fprintf(stderr, "Error setting GPIO value for pin %d\n", gpio_pins[i]);
            }
        }

        // Print GPIO states
        printf("GPIO States: ");
        for (int i = 0; i < num_pins; i++) {
            int value = get_gpio_value(lines[i]);
            if (value >= 0) {
                printf("GPIO%d=%d ", gpio_pins[i], value);
            } else {
                printf("GPIO%d=Error ", gpio_pins[i]);
            }
        }
        printf("\n");

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

