#define PWM_RANGE 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_11, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(GPIO_8, PWM_RANGE);
    gpioSetPWMrange(GPIO_9, PWM_RANGE);
    gpioSetPWMrange(GPIO_11, PWM_RANGE);
    gpioSetPWMrange(GPIO_18, PWM_RANGE);

    // Main loop
    while (program_running) {
        // Set PWM duty cycle for each GPIO pin
        gpioPWM(GPIO_8, 500); // 50% duty cycle
        gpioPWM(GPIO_9, 250); // 25% duty cycle
        gpioPWM(GPIO_11, 750); // 75% duty cycle
        gpioPWM(GPIO_18, 1000); // 100% duty cycle

        // Print the state of the GPIO pins
        printf("GPIO 8: %d, GPIO 9: %d, GPIO 11: %d, GPIO 18: %d\n",
               gpioGetPWMdutycycle(GPIO_8),
               gpioGetPWMdutycycle(GPIO_9),
               gpioGetPWMdutycycle(GPIO_11),
               gpioGetPWMdutycycle(GPIO_18));

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output and release GPIO pins
    gpioPWM(GPIO_8, 0);
    gpioPWM(GPIO_9, 0);
    gpioPWM(GPIO_11, 0);
    gpioPWM(GPIO_18, 0);

    // Terminate pigpio library
