#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_YUYV

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers;
unsigned int n_buffers;

static int fd = -1; // File descriptor for the video device
static int running = 1; // Flag to control the main loop

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    FILE *fp;
    char filename[64];
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return 1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return 1;
    }

    // Map the buffers
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Queue the buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        free(buffers);
        return 1;
    }

    // Capture and save images
    while (running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break; // Exit loop on error
        }

        // Generate filename with timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "image_%Y%m%d_%H%M%S.jpg", timeinfo);

        // Save the image to a file
        fp = fopen(filename, "wb");
        if (fp == NULL) {
            perror("Error opening file for writing");
            break; // Exit loop on error
        }

        fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
        fclose(fp);

        // Requeue the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error requeuing buffer");
            break; // Exit loop on error
        }

        printf("Captured and saved image: %s\n", filename);
        usleep(100000); // 0.1 seconds
    }

    // Stop streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
    }

    // Unmap buffers
    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    // Free buffers
    free(buffers);

    // Close the device
    close(fd);

    return 0;
}

