#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 10;

    while (!terminate) {
        // Set PWM duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the current duty cycle
        printf("PWM Duty Cycle: %d\n", duty_cycle);

        // Update duty cycle
        duty_cycle += increment;

        // Reverse direction if reaching the limits
        if (duty_cycle >= PWM_RANGE) {
            increment = -10;
        } else if (duty_cycle <= 0) {
            increment = 10;
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO 18
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input (safer)

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

