#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27

int main() {
    int file;
    int i2c_fd;
    unsigned char data[16]; // Buffer to hold the data to display
    int bytes_read;

    // Open the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Specify the address of the PCF8574
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Example data to display (replace with your actual data)
    for (int i = 0; i < 16; i++) {
        data[i] = (i % 2 == 0) ? 0xFF : 0x00; // Alternating full and empty bytes
    }

