#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400     // cm
#define TIMEOUT_US 200000     // 200ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;
int terminate_flag = 0;

// Function prototypes
void trigger_pulse();
long pulse_width();
float calculate_distance(long pulse_width);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    terminate_flag = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for the echo pin to go high (start of pulse)
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo start.\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Wait for the echo pin to go low (end of pulse)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (timeout++ > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end.\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);

            if (distance > 0 && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Error: No echo received or timeout.\n");
        }

        gpioDelay(500); // Delay between measurements
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line as output */
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO line high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Wait 5 seconds */
        sleep(5);

        /* Set GPIO line low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        /* Wait 5 seconds */
        sleep(5);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variables for signal handling
static volatile int keep_running = 1;
static int i2c_fd = -1;

// Signal handler function
void int_handler(int dummy)
{
    keep_running = 0;
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return data;
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t data[2];
    data[0] = reg;
    data[1] = value;
    if (write(fd, data, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers
int16_t i2c_read_word(int fd, uint8_t reg)
{
    int16_t high = i2c_read_reg(fd, reg);
    int16_t low = i2c_read_reg(fd, reg + 1);

    if (high == -1 || low == -1) {
        return -1; // Indicate error
    }

    return (high << 8) | low;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read accelerometer data
        int16_t accel_x = i2c_read_word(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = i2c_read_word(i2c_fd, ACCEL_YOUT_H);
        int16_t accel_z = i2c_read_word(i2c_fd, ACCEL_ZOUT_H);

        if (accel_x == -1 || accel_y == -1 || accel_z == -1) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        } else {
            // Print the data
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        }

        // Delay for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&ts, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

static struct gpiod_chip *chip;
static struct gpiod_line *line_2, *line_3, *line_17;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time = {5, 0}; // 5 seconds
    int cycle = 0;
    int gpio_states[3] = {0, 0, 0}; // Initial states for GPIOs 2, 3, 17

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line_2, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_3, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_17, "my_program", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (cycle < 3 && !terminate) {
        // Set GPIO states
        gpio_states[0] = (cycle % 2 == 0) ? 1 : 0; // Toggle GPIO 2
        gpio_states[1] = (cycle % 3 == 0) ? 1 : 0; // Toggle GPIO 3 every 3 cycles
        gpio_states[2] = (cycle % 4 == 0) ? 1 : 0; // Toggle GPIO 17 every 4 cycles

        // Apply states to GPIOs
        ret = gpiod_line_set_value(line_2, gpio_states[0]);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            break;
        }

        ret = gpiod_line_set_value(line_3, gpio_states[1]);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            break;
        }

        ret = gpiod_line_set_value(line_17, gpio_states[2]);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            break;
        }

        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Print current state
        printf("%s - GPIO 2: %d, GPIO 3: %d, GPIO 17: %d\n", buf, gpio_states[0], gpio_states[1], gpio_states[2]);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);

        cycle++;
    }

    // Release GPIO lines
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_line_release(line_17);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17, *line22, *line27;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
int get_gpio_output(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line22, struct gpiod_line *line27);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line17, line22, line27);
    exit(0);
}

// Function to setup a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request(*line, "my_program", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT)) {
        fprintf(stderr, "Error: Could not request line for GPIO %d\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value)) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line22, struct gpiod_line *line27) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_17, &line17) != 0) {
        cleanup_gpio(chip, NULL, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_22, &line22) != 0) {
        cleanup_gpio(chip, line17, NULL, NULL);
        return 1;
    }
    if (setup_gpio(chip, GPIO_27, &line27) != 0) {
        cleanup_gpio(chip, line17, line22, NULL);
        return 1;
    }

    // Set GPIO output values
    if (set_gpio_output(line17, 1) != 0) {
        cleanup_gpio(chip, line17, line22, line27);
        return 1;
    }
    if (set_gpio_output(line22, 0) != 0) {
        cleanup_gpio(chip, line17, line22, line27);
        return 1;
    }
    if (set_gpio_output(line27, 1) != 0) {
