#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio18_line = NULL;
struct gpiod_line *gpio27_line = NULL;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
int get_gpio_output(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_line *line);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio(gpio17_line);
    cleanup_gpio(gpio18_line);
    cleanup_gpio(gpio27_line);
    exit(0);
}

// Function to setup a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!(*line)) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request_output(*line, "my_program", 0) < 0) {
        fprintf(stderr, "Error: Could not request line for GPIO %d as output\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup a GPIO line
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_17, &gpio17_line) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_18, &gpio18_line) < 0) {
        cleanup_gpio(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_27, &gpio27_line) < 0) {
        cleanup_gpio(gpio17_line);
        cleanup_gpio(gpio18_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 17
        if (set_gpio_output(gpio17_line, 1) < 0) {
            break;
        }
        printf("GPIO 17: 1\n");
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio17_line, 0) < 0) {
            break;
        }
        printf("GPIO 17: 0\n");
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 18
        if (set_gpio_output(gpio18_line, 1) < 0) {
            break;
        }
        printf("GPIO 18: 1\n");
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio18_line, 0) < 0) {
            break;
        }
        printf("GPIO 18: 0\n");
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 27
        if (set_gpio_output(gpio27_line, 1) < 0) {
            break;
        }
        printf("GPIO 27: 1\n");
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio27_line, 0) < 0) {
            break;
        }
        printf("GPIO 27: 0\n");
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup GPIO lines
    cleanup_gpio(gpio17_line);
    cleanup_gpio(gpio18_line);
    cleanup_gpio(gpio27_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06

int i2c_fd;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    close(i2c_fd);
    exit(0);
}

// Function to read data from SHT31
int read_sht31(float *temperature, float *humidity) {
    uint8_t write_data[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t read_data[6];

    // Write measurement command
    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement (typical conversion time is 10ms, but let's wait 20ms)
    usleep(20000);

    // Read 6 bytes of data
    if (read(i2c_fd, read_data, 6) != 6) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert data
    int temperature_raw = (read_data[0] << 8) | read_data[1];
    int humidity_raw = (read_data[3] << 8) | read_data[4];

    // Calculate temperature (Celsius)
    *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);

    // Calculate relative humidity (%)
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to validate temperature and humidity readings
int validate_reading(float temperature, float humidity) {
    if (temperature < -40.0 || temperature > 125.0) {
        fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", temperature);
        return -1;
    }
    if (humidity < 0.0 || humidity > 100.0) {
        fprintf(stderr, "Error: Invalid humidity reading: %.2f\n", humidity);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    while (1) {
        // Read temperature and humidity
        if (read_sht31(&temperature, &humidity) == 0) {
            // Validate readings
            if (validate_reading(temperature, humidity) == 0) {
                // Print temperature and humidity
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Failed to read SHT31 data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

