#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency to 1 kHz (1000 Hz)
    gpioSetPWMfrequency(PWM_GPIO, 1000);

    // Set PWM range (resolution) to 1000
    gpioSetPWMrange(PWM_GPIO, 1000);

    // Set PWM duty cycle to 50% (500)
    gpioPWM(PWM_GPIO, 500);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("PWM signal started on GPIO %d. Press Ctrl+C to stop.\n", PWM_GPIO);

    while (!terminate) {
        // Keep the program running until a signal is received
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Stop PWM signal
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input (safer)

    // Terminate pigpio
    gpioTerminate();

    printf("PWM signal stopped on GPIO %d. pigpio terminated.\n", PWM_GPIO);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_PIN2 3
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line *line2;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    int retries = 0;
    struct timespec delay = {0, 100000000}; // 100ms
    int current_state = 0;
    int current_state2 = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!line2) {
        perror("Error getting GPIO line2");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        // Toggle GPIO 2
        current_state = !current_state;
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_PIN, strerror(-ret));
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached for GPIO %d. Giving up.\n", GPIO_PIN);
                break;
            }
            nanosleep(&delay, NULL);
            continue;
        }
        retries = 0; // Reset retries on success
        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);

        // Toggle GPIO 3
        current_state2 = !current_state2;
        ret = gpiod_line_set_value(line2, current_state2);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_PIN2, strerror(-ret));
            retries++;
            if (retries > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached for GPIO %d. Giving up.\n", GPIO_PIN2);
                break;
            }
            nanosleep(&delay, NULL);
            continue;
        }
        retries = 0; // Reset retries on success
        printf("GPIO %d set to %d\n", GPIO_PIN2, current_state2);

        nanosleep(&delay, NULL);
    }

    printf("Cleaning up...\n");
    gpiod_line_set_value(line, 0); // Set to 0 before releasing
    gpiod_line_set_value(line2, 0); // Set to 0 before releasing
    gpiod_line_release(line);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

