static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line as output */
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO output to HIGH */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);
        sleep(30);

        /* Set GPIO output to LOW */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);
        sleep(30);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between state changes (in milliseconds)
#define DELAY_MS 500

// Global variables for GPIO lines and chip
struct gpiod_line *gpio2_line = NULL;
struct gpiod_line *gpio3_line = NULL;
struct gpiod_line *gpio17_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close GPIO lines
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio2_line = gpiod_chip_get_line(chip, GPIO_2);
    gpio3_line = gpiod_chip_get_line(chip, GPIO_3);
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);

    if (!gpio2_line || !gpio3_line || !gpio17_line) {
        perror("Error getting GPIO line");
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio2_line, &config, 0) < 0 ||
        gpiod_line_request(gpio3_line, &config, 0) < 0 ||
        gpiod_line_request(gpio17_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        if (gpio2_line) gpiod_line_release(gpio2_line);
        if (gpio3_line) gpiod_line_release(gpio3_line);
        if (gpio17_line) gpiod_line_release(gpio17_line);
        if (chip) gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Cycle 1: GPIO 2 ON, GPIO 3 OFF, GPIO 17 OFF
        if (gpiod_line_set_value(gpio2_line, 1) < 0) {
            perror("Error setting GPIO 2 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio3_line, 0) < 0) {
            perror("Error setting GPIO 3 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio17_line, 0) < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 2 ON, GPIO 3 OFF, GPIO 17 OFF\n", i + 1);
        usleep(DELAY_MS * 1000); // Delay for 500ms

        // Cycle 2: GPIO 2 OFF, GPIO 3 ON, GPIO 17 OFF
        if (gpiod_line_set_value(gpio2_line, 0) < 0) {
            perror("Error setting GPIO 2 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio3_line, 1) < 0) {
            perror("Error setting GPIO 3 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio17_line, 0) < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 2 OFF, GPIO 3 ON, GPIO 17 OFF\n", i + 1);
        usleep(DELAY_MS * 1000); // Delay for 500ms

        // Cycle 3: GPIO 2 OFF, GPIO 3 OFF, GPIO 17 ON
        if (gpiod_line_set_value(gpio2_line, 0) < 0) {
            perror("Error setting GPIO 2 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio3_line, 0) < 0) {
            perror("Error setting GPIO 3 value");
            goto cleanup;
        }
        if (gpiod_line_set_value(gpio17_line, 1) < 0) {
            perror("Error setting GPIO 17 value");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 2 OFF, GPIO 3 OFF, GPIO 17 ON\n", i + 1);
        usleep(DELAY_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
cleanup:
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

