#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_12 12
#define GPIO_17 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio10_line = NULL;
struct gpiod_line *gpio11_line = NULL;
struct gpiod_line *gpio12_line = NULL;
struct gpiod_line *gpio17_line = NULL;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
int get_gpio_output(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_line *line);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio(gpio10_line);
    cleanup_gpio(gpio11_line);
    cleanup_gpio(gpio12_line);
    cleanup_gpio(gpio17_line);
    exit(0);
}

// Function to setup a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!(*line)) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_request_output(*line, "my_program", 0) < 0) {
        fprintf(stderr, "Error: Could not request line for GPIO %d as output\n", gpio_pin);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup a GPIO line
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_10, &gpio10_line) < 0) goto cleanup;
    if (setup_gpio(chip, GPIO_11, &gpio11_line) < 0) goto cleanup;
    if (setup_gpio(chip, GPIO_12, &gpio12_line) < 0) goto cleanup;
    if (setup_gpio(chip, GPIO_17, &gpio17_line) < 0) goto cleanup;

    // Main loop
    while (1) {
        // Toggle GPIO 10 and 11
        if (set_gpio_output(gpio10_line, 1) < 0) goto cleanup;
        if (set_gpio_output(gpio11_line, 0) < 0) goto cleanup;
        nanosleep(&sleep_time, NULL);

        if (set_gpio_output(gpio10_line, 0) < 0) goto cleanup;
        if (set_gpio_output(gpio11_line, 1) < 0) goto cleanup;
        nanosleep(&sleep_time, NULL);

        // Set GPIO 12 and 17 to 1
        if (set_gpio_output(gpio12_line, 1) < 0) goto cleanup;
        if (set_gpio_output(gpio17_line, 1) < 0) goto cleanup;
        nanosleep(&sleep_time, NULL);

        // Set GPIO 12 and 17 to 0
        if (set_gpio_output(gpio12_line, 0) < 0) goto cleanup;
        if (set_gpio_output(gpio17_line, 0) < 0) goto cleanup;
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Cleanup GPIO lines
    cleanup_gpio(gpio10_line);
    cleanup_gpio(gpio11_line);
    cleanup_gpio(gpio12_line);
    cleanup_gpio(gpio17_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 1;
}

