#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define NUM_PIXELS 3
#define CYCLES 3
#define DELAY_US 5000 // 0.005 seconds in microseconds

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Define color values (RGB)
    unsigned int colors[NUM_PIXELS] = {0xFF0000, 0x00FF00, 0x0000FF};

    // Apply colors to the strip
    for (int cycle = 0; cycle < CYCLES; cycle++) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            gpioWrite(GPIO_PIN, (colors[i] >> 16) & 0xFF); // Red
            gpioDelay(1000); // Short delay for each bit
            gpioWrite(GPIO_PIN, (colors[i] >> 8) & 0xFF);  // Green
            gpioDelay(1000);
            gpioWrite(GPIO_PIN, colors[i] & 0xFF);       // Blue
            gpioDelay(1000);
        }
        gpioDelay(DELAY_US);
    }

    gpioTerminate();
    return 0;
}

