    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec delay = {0, 100000000}; // 100ms

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as output
    ret = gpiod_line_request_output(line, "my_program", 0); // Initial value 0
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (line %d) set to output, initial value: %d\n", GPIO_PIN, GPIO_LINE, 0);

    // Main loop
    while (!terminate) {
        // Toggle GPIO state
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
