#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define DUTY_CYCLE 50 // 50% duty cycle

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time = {5, 0}; // 5 seconds
    struct timespec remaining_time;

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "duty_cycle_control", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Set GPIO HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Sleep for half the period (50% duty cycle)
        nanosleep(&sleep_time, &remaining_time);
        sleep_time.tv_sec = 5;
        sleep_time.tv_nsec = 0;

        // Set GPIO LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Sleep for the remaining half period
        nanosleep(&remaining_time, &remaining_time);
        sleep_time.tv_sec = 5;
        sleep_time.tv_nsec = 0;
    }

    // Release GPIO line
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 4
#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to write to a file
int write_to_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to file %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

// Function to read from a file
int read_from_file(const char *path, char *buffer, size_t buffer_size) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(buffer, buffer_size, fp) == NULL && ferror(fp)) {
        fprintf(stderr, "Error reading from file %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

// Function to read temperature from DS18B20
float read_temperature() {
    char device_id[256];
    char w1_slave_path[512];
    char w1_slave[256];
    int retries = 0;

    // Find the DS18B20 device ID
    DIR *dir;
    struct dirent *ent;
    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening directory %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return -1000.0; // Indicate error
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strcpy(device_id, ent->d_name);
            break;
        }
    }
    closedir(dir);

    if (strlen(device_id) == 0) {
        fprintf(stderr, "Error: DS18B20 device not found.\n");
        return -1000.0; // Indicate error
    }

    // Construct the w1_slave file path
    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s/w1_slave", W1_DEVICES_DIR, device_id);

    // Read the w1_slave file
    while (retries < MAX_RETRIES) {
        if (read_from_file(w1_slave_path, w1_slave, sizeof(w1_slave)) == 0) {
            // Check for CRC error
            if (strstr(w1_slave, "YES") != NULL) {
                // Extract temperature
                char *temp_str = strstr(w1_slave, "t=");
                if (temp_str != NULL) {
                    long temp_raw = strtol(temp_str + 2, NULL, 10);
                    float temperature = (float)temp_raw / 1000.0;
                    return temperature;
                } else {
                    fprintf(stderr, "Error: Temperature data not found in w1_slave output.\n");
                }
            } else {
                fprintf(stderr, "Error: CRC check failed. Retrying...\n");
            }
            retries++;
            sleep(1); // Wait before retrying
        } else {
            fprintf(stderr, "Error reading w1_slave file. Retrying...\n");
            retries++;
            sleep(1);
        }
    }

    fprintf(stderr, "Error: Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1000.0; // Indicate error
}

int main() {
    signal(SIGINT, signal_handler);

    printf("Starting temperature readings...\n");

    for (int i = 0; i < 3 && program_running; i++) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }
        sleep(5);
    }

    printf("Exiting.\n");
    return 0;
}

