#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define MAX_DISTANCE 400 // Maximum measurable distance in cm
#define TIMEOUT_US 200000  // Timeout in microseconds (0.2 seconds)

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

float get_distance() {
    long long start_tick, end_tick, diff;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (time * speed of sound) / 2
    // time = diff / 1000000.0 (seconds)
    // speed of sound = 34300 cm/s
    // distance = (diff / 1000000.0 * 34300) / 2
    float distance = (float)diff / 1000000.0 * 34300.0 / 2.0;

    return distance;
}

