    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_pulse();
        float distance = get_distance();

        if (distance > 0 && distance <= MAX_DISTANCE) {
            printf("Distance: %.2f cm\n", distance);
        } else if (distance == -1.0) {
            fprintf(stderr, "Error: Timeout or invalid reading\n");
        } else {
            fprintf(stderr, "Error: Distance out of range\n");
        }

        gpioDelay(100); // 0.1 seconds
    }

    gpioTerminate();
    return 0;
}

