    for (i = 0; i < 40; i++) {
        if (timings[2 * i + 1] > MIN_TIMING) {
            data[bit_count / 8] <<= 1;
            if (timings[2 * i] > MIN_TIMING) {
                data[bit_count / 8] |= 1;
            }
            bit_count++;
        }
    }

    if (bit_count != 40) {
        fprintf(stderr, "Invalid data length: %d bits\n", bit_count);
        return -1;
    }

    int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum failure: calculated %d, received %d\n", checksum, data[4]);
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int valid_readings = 0;
    time_t start_time = time(NULL);

    while (!terminate && valid_readings < 3) {
        if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
            printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
            valid_readings++;
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }
        sleep(2);
    }

    if (valid_readings < 3) {
        fprintf(stderr, "Failed to get 3 valid readings within the time limit.\n");
    }

    gpioTerminate();
    return 0;
}

