#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line4, *line17, *line18;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 50000000}; // 0.05 seconds
    int cycle = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line4 || !line17 || !line18) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line4, "my_program", 0);
    ret |= gpiod_line_request_output(line17, "my_program", 0);
    ret |= gpiod_line_request_output(line18, "my_program", 0);

    if (ret) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (cycle < 5 && !terminate) {
        // Cycle 1: 4 HIGH, 17 LOW, 18 LOW
        ret = gpiod_line_set_value(line4, 1);
        ret |= gpiod_line_set_value(line17, 0);
        ret |= gpiod_line_set_value(line18, 0);
        if (ret) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO4=HIGH, GPIO17=LOW, GPIO18=LOW\n", cycle + 1);
        nanosleep(&sleep_time, NULL);

        // Cycle 2: 4 LOW, 17 HIGH, 18 LOW
        ret = gpiod_line_set_value(line4, 0);
        ret |= gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line18, 0);
        if (ret) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO4=LOW, GPIO17=HIGH, GPIO18=LOW\n", cycle + 2);
        nanosleep(&sleep_time, NULL);

        // Cycle 3: 4 LOW, 17 LOW, 18 HIGH
        ret = gpiod_line_set_value(line4, 0);
        ret |= gpiod_line_set_value(line17, 0);
        ret |= gpiod_line_set_value(line18, 1);
        if (ret) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO4=LOW, GPIO17=LOW, GPIO18=HIGH\n", cycle + 3);
        nanosleep(&sleep_time, NULL);

        // Cycle 4: 4 HIGH, 17 HIGH, 18 LOW
        ret = gpiod_line_set_value(line4, 1);
        ret |= gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line18, 0);
        if (ret) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO4=HIGH, GPIO17=HIGH, GPIO18=LOW\n", cycle + 4);
        nanosleep(&sleep_time, NULL);

        // Cycle 5: 4 LOW, 17 HIGH, 18 HIGH
        ret = gpiod_line_set_value(line4, 0);
        ret |= gpiod_line_set_value(line17, 1);
        ret |= gpiod_line_set_value(line18, 1);
        if (ret) {
            perror("Error setting GPIO value");
            break;
        }
        printf("Cycle %d: GPIO4=LOW, GPIO17=HIGH, GPIO18=HIGH\n", cycle + 5);
        nanosleep(&sleep_time, NULL);

        cycle += 5;
    }

    gpiod_line_set_value(line4, 0);
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line18, 0);

    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, defaults to 255)
    gpioSetPWMrange(PWM_GPIO, 1000);

    // Apply PWM signal (50% duty cycle)
    gpioPWM(PWM_GPIO, 500); // 50% of 1000

    printf("PWM signal applied to GPIO %d at %d Hz, 50%% duty cycle\n", PWM_GPIO, PWM_FREQUENCY);

    // Keep the program running for a while
    sleep(5);

    // Stop PWM signal
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input to release

    gpioTerminate();

    printf("PWM stopped and GPIO released.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

#define NUM_GPIOS 7
const int GPIO_PINS[NUM_GPIOS] = {4, 17, 22, 23, 24, 25, 27};

struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i, ret;
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds
    int states[NUM_GPIOS] = {0, 1, 0, 1, 0, 1, 0}; // Initial states

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Open lines for each GPIO pin
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error opening GPIO line %d\n", GPIO_PINS[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "my_program", 0); // Request as output, initial value 0
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %d\n", GPIO_PINS[i], ret);
            goto cleanup;
        }

        // Set initial state
        ret = gpiod_line_set_value(lines[i], states[i]);
        if (ret < 0) {
            fprintf(stderr, "Error setting initial value for GPIO %d: %d\n", GPIO_PINS[i], ret);
            goto cleanup;
        }
    }

    // Main loop
    for (i = 0; i < 100 && !terminate; i++) {
        for (int j = 0; j < NUM_GPIOS; j++) {
            ret = gpiod_line_set_value(lines[j], states[j]);
            if (ret < 0) {
                fprintf(stderr, "Error setting value for GPIO %d: %d\n", GPIO_PINS[j], ret);
                goto cleanup;
            }
            printf("GPIO %d: %d\n", GPIO_PINS[j], states[j]);
        }
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    for (i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_23 23

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio18_line = NULL;
struct gpiod_line *gpio23_line = NULL;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line);
int set_gpio_output(struct gpiod_line *line, int value);
int get_gpio_output(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_line *line);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio(gpio17_line);
    cleanup_gpio(gpio18_line);
    cleanup_gpio(gpio23_line);
    exit(0);
}

// Function to setup a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio_pin, struct gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!(*line)) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line for GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to set the output value of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO line\n");
        return -1;
    }
    return 0;
}

// Function to get the output value of a GPIO line
int get_gpio_output(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO line\n");
        return -1;
    }
    return value;
}

// Function to cleanup a GPIO line
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIO_CHIP);
        return 1;
    }

    // Setup GPIO lines
    if (setup_gpio(chip, GPIO_17, &gpio17_line) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_18, &gpio18_line) != 0) {
        cleanup_gpio(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (setup_gpio(chip, GPIO_23, &gpio23_line) != 0) {
        cleanup_gpio(gpio17_line);
        cleanup_gpio(gpio18_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO output values
    if (set_gpio_output(gpio17_line, 1) != 0) {
        cleanup_gpio(gpio17_line);
        cleanup_gpio(gpio18_line);
        cleanup_gpio(gpio23_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (set_gpio_output(gpio18_line, 0) != 0) {
        cleanup_gpio(gpio17_line);
        cleanup_gpio(gpio18_line);
        cleanup_gpio(gpio23_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (set_gpio_output(gpio23_line, 1) != 0) {
        cleanup_gpio(gpio17_line);
        cleanup_gpio(gpio18_line);
        cleanup_gpio(gpio23_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get and print GPIO output values
    int value17 = get_gpio_output(gpio17_line);
    int value18 = get_gpio_output(gpio18_line);
    int value23 = get_gpio_output(gpio23_line);

    if (value17 >= 0 && value18 >= 0 && value23 >= 0) {
        printf("GPIO 17: %d\n", value17);
        printf("GPIO 18: %d\n", value18);
        printf("GPIO 23: %d\n", value23);
    } else {
        fprintf(stderr, "Error: Could not read GPIO values\n");
    }

    // Cleanup GPIO lines and close chip
    cleanup_gpio(gpio17_line);
    cleanup_gpio(gpio18_line);
    cleanup_gpio(gpio23_line);
    gpiod_chip_close(chip);

    return 0;
}

