#define PWM_PIN_3 18
#define PWM_PIN_4 27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define PWM range
#define PWM_RANGE 1000

// Define PWM duty cycle values
#define DUTY_CYCLE_1 200
#define DUTY_CYCLE_2 400
#define DUTY_CYCLE_3 600
#define DUTY_CYCLE_4 800

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency
