    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    for (int cycle = 1; cycle <= 5 && program_running; cycle++) {
        printf("Cycle %d starting...\n", cycle);

        // Set PWM duty cycles
        gpioPWM(PWM_PIN_1, DUTY_CYCLE_1);
        gpioPWM(PWM_PIN_2, DUTY_CYCLE_2);
        gpioPWM(PWM_PIN_3, DUTY_CYCLE_3);
        gpioPWM(PWM_PIN_4, DUTY_CYCLE_4);

        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Report the state
        printf("%s: GPIO %d (PWM): %d, GPIO %d (PWM): %d, GPIO %d (PWM): %d, GPIO %d (PWM): %d\n",
               buf, PWM_PIN_1, DUTY_CYCLE_1, PWM_PIN_2, DUTY_CYCLE_2, PWM_PIN_3, DUTY_CYCLE_3, PWM_PIN_4, DUTY_CYCLE_4);

        // Wait for 60 seconds
        sleep(60);

        // Stop PWM output
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        gpioPWM(PWM_PIN_4, 0);

        printf("Cycle %d finished.\n", cycle);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

