#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define DHT22_GPIO 4

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30us

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Wait for the DHT22 to pull the line high
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Timeout after 100 us
    }

    // Read the 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -1; // Timeout after 100 us
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        return -1; // Checksum error
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    for (int i = 0; i < 3 && !terminate; i++) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22 read failed. Checksum error or timeout.\n");
        }

        sleep(60);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles in seconds
#define DELAY_SECONDS 1

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[5];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(struct gpiod_chip *chip, int gpio, int direction);
int set_gpio_value(struct gpiod_line *line, int value);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *lines[], int num_lines);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
}

// Function to set up a GPIO line
int setup_gpio(struct gpiod_chip *chip, int gpio, int direction) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_request(line, "my_program", direction);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request line for GPIO %d, error code: %d\n", gpio, ret);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO line, error code: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to clean up GPIO lines
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *lines[], int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO lines
    int gpios[] = {GPIO_8, GPIO_9, GPIO_10, GPIO_11, GPIO_23};
    for (int i = 0; i < 5; i++) {
        if (setup_gpio(chip, gpios[i], GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
    }

    // Main loop
    for (int cycle = 0; cycle < NUM_CYCLES && !terminate; cycle++) {
        // Set GPIO 8 HIGH
        if (set_gpio_value(lines[0], 1) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        printf("Cycle %d: GPIO %d set HIGH\n", cycle + 1, GPIO_8);

        // Set GPIO 9 LOW
        if (set_gpio_value(lines[1], 0) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        printf("Cycle %d: GPIO %d set LOW\n", cycle + 1, GPIO_9);

        // Set GPIO 10 HIGH
        if (set_gpio_value(lines[2], 1) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        printf("Cycle %d: GPIO %d set HIGH\n", cycle + 1, GPIO_10);

        // Set GPIO 11 LOW
        if (set_gpio_value(lines[3], 0) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        printf("Cycle %d: GPIO %d set LOW\n", cycle + 1, GPIO_11);

        // Set GPIO 23 HIGH
        if (set_gpio_value(lines[4], 1) != 0) {
            cleanup_gpio(chip, lines, 5);
            return 1;
        }
        printf("Cycle %d: GPIO %d set HIGH\n", cycle + 1, GPIO_23);

        // Wait for 1 second
        sleep(DELAY_SECONDS);
    }

    // Clean up GPIO lines
    cleanup_gpio(chip, lines, 5);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
