#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to output
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(GPIO_17, 1000);
    gpioSetPWMfrequency(GPIO_18, 1000);
    gpioSetPWMfrequency(GPIO_27, 1000);

    // Set PWM range to 1000
    gpioSetPWMrange(GPIO_17, 1000);
    gpioSetPWMrange(GPIO_18, 1000);
    gpioSetPWMrange(GPIO_27, 1000);

    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 1;

    while (!terminate) {
        // Set PWM duty cycle for each GPIO
        gpioPWM(GPIO_17, duty_cycle);
        gpioPWM(GPIO_18, duty_cycle);
        gpioPWM(GPIO_27, duty_cycle);

        // Print the current duty cycle
