        // Update duty cycle
        duty_cycle += increment;

        // Reverse direction if reaching limits
        if (duty_cycle >= 1000) {
            duty_cycle = 999;
            increment = -1;
        } else if (duty_cycle <= 0) {
            duty_cycle = 1;
            increment = 1;
        }

        // Wait for 1 second
