#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// Define the SPI device path
#define SPI_DEVICE "/dev/spidev0.0"

// Define the SPI mode
#define SPI_MODE SPI_MODE_0

// Define the SPI clock speed
#define SPI_SPEED 1000000 // 1 MHz

// Define the chip select mode
#define SPI_CS_MODE SPI_CS_HIGH

// Global variable to store the SPI file descriptor
int spi_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read data from the MAX31855
int read_max31855(int fd, float *internal_temp, float *thermocouple_temp) {
    uint8_t data[4];
    int ret;
    uint32_t raw_data;

    // Read 4 bytes from the SPI device
    ret = read(fd, data, 4);
    if (ret != 4) {
        fprintf(stderr, "Error reading from SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes into a 32-bit integer
    raw_data = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];

    // Check for fault conditions
    if (raw_data & 0x00000007) {
        fprintf(stderr, "MAX31855 Fault detected: ");
        if (raw_data & 0x00000001) fprintf(stderr, "Open circuit\n");
        if (raw_data & 0x00000002) fprintf(stderr, "Short to GND\n");
        if (raw_data & 0x00000004) fprintf(stderr, "Short to VCC\n");
        return -1;
    }

    // Extract the internal temperature
    int16_t internal_temp_raw = (raw_data >> 18) & 0x3FFF; // Mask out the relevant bits
    if (internal_temp_raw & 0x2000) {
        internal_temp_raw |= 0xFFFFC000; // Sign extend if negative
    }
    *internal_temp = internal_temp_raw * 0.0625;

    // Extract the thermocouple temperature
    int16_t thermocouple_temp_raw = (raw_data >> 4) & 0x3FFF; // Mask out the relevant bits
    if (thermocouple_temp_raw & 0x2000) {
        thermocouple_temp_raw |= 0xFFFFC000; // Sign extend if negative
    }
    *thermocouple_temp = thermocouple_temp_raw * 0.25;

    return 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure the SPI device
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    uint8_t cs_mode = SPI_CS_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &cs_mode) < 0) {
        fprintf(stderr, "Error setting SPI CS mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    float internal_temp, thermocouple_temp;

    // Read the MAX31855 data
    if (read_max31855(spi_fd, &internal_temp, &thermocouple_temp) == 0) {
        printf("Internal Temperature: %.2f °C\n", internal_temp);
        printf("Thermocouple Temperature: %.2f °C\n", thermocouple_temp);
    } else {
        fprintf(stderr, "Failed to read MAX31855 data.\n");
        close(spi_fd);
        return 1;
    }

    // Close the SPI device
    close(spi_fd);

    return 0;
}

