#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define LED_PIN 18
#define BUTTON_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds in microseconds

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line, *led_line, *button_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int setup_gpio();
void trigger_pulse();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void control_led(float distance);
void button_interrupt_handler(int signum);
void cleanup();
void signal_handler(int signum);

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
} gpio_line_t;

// Function to set up GPIO lines
int setup_gpio_lines(gpio_line_t *lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        lines[i].line = gpiod_chip_get_line(chip, lines[i].pin);
        if (!lines[i].line) {
            fprintf(stderr, "Error getting line %d\n", lines[i].pin);
            return -1;
        }
        if (gpiod_line_request_output(lines[i].line, "my_program", 0) < 0) {
            fprintf(stderr, "Error requesting line %d as output\n", lines[i].pin);
            return -1;
        }
    }
    return 0;
}

// Function to release GPIO lines
void release_gpio_lines(gpio_line_t *lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i].line);
    }
}

int main() {
    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        // Control the LED based on the distance
        control_led(distance);

        // Check button state
        if (gpiod_line_get_value(button_line) == 1) {
            button_interrupt_handler(SIGINT);
        }

        // Delay to avoid overwhelming the sensor
        usleep(100000); // 0.1 seconds
    }

    // Cleanup GPIO
    cleanup();

    return 0;
}

// Function to set up GPIO
int setup_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    // Request GPIO lines
    gpio_line_t trigger_output = {0};
    gpio_line_t echo_input = {0};
    gpio_line_t led_output = {0};
    gpio_line_t button_input = {0};

    trigger_output.pin = TRIGGER_PIN;
    echo_input.pin = ECHO_PIN;
    led_output.pin = LED_PIN;
    button_input.pin = BUTTON_PIN;

    if (setup_gpio_lines(&trigger_output, 1) < 0 ||
        setup_gpio_lines(&echo_input, 1) < 0 ||
        setup_gpio_lines(&led_output, 1) < 0 ||
        setup_gpio_lines(&button_input, 1) < 0) {
        gpiod_chip_close(chip);
        return -1;
    }

    // Set echo pin as input
    gpiod_line_request_input(echo_line, "my_program");

    // Set up interrupt for button press
    struct gpiod_line_event event;
    if (gpiod_line_request_rising_edge_events(button_line, "my_program") < 0) {
        fprintf(stderr, "Error requesting rising edge events for button\n");
        cleanup();
        return -1;
    }

    return 0;
}

// Function to trigger a pulse on the trigger pin
void trigger_pulse() {
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);
}

// Function to measure the pulse width on the echo pin
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width;

    // Wait for the echo pin to go high (start of pulse)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec) > TIMEOUT_US * 1000000L) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
    }

    // Wait for the echo pin to go low (end of pulse)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec) > TIMEOUT_US * 1000000L) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
    pulse_width /= 1000; // Convert to microseconds

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 2 for one-way distance
}

// Function to control the LED based on the distance
void control_led(float distance) {
    if (distance > 0 && distance < 50) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Function to handle button press interrupt
void button_interrupt_handler(int signum) {
    printf("Button pressed! Exiting.\n");
    program_running = 0;
}

// Function to handle Ctrl+C signal
void signal_handler(int signum) {
    printf("Ctrl+C pressed! Exiting.\n");
    program_running = 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);
}

