#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {1, 0}; // 1 second
    int i;

    /* Set up signal handling */
    signal(SIGINT, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line as output */
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d (BCM) initialized as output.\n", GPIO_PIN);

    /* Main loop */
    for (i = 0; !terminate; i++) {
        /* Set GPIO line high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO line high");
            break;
        }
        printf("GPIO %d (BCM) set HIGH.\n", GPIO_PIN);

        /* Sleep for 1 second */
        nanosleep(&sleep_time, NULL);

        /* Set GPIO line low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO line low");
            break;
        }
        printf("GPIO %d (BCM) set LOW.\n", GPIO_PIN);

        /* Sleep for 1 second */
        nanosleep(&sleep_time, NULL);
    }

    /* Release GPIO line */
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("Error releasing GPIO line");
    }

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("GPIO %d (BCM) released.\n", GPIO_PIN);

    return EXIT_SUCCESS;
}

