// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// Register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the VEML7700
int read_veml7700(uint16_t *value) {
    uint8_t buffer[2];
    int result;

    // Read two bytes from the ALS_DATA register
    result = read(i2c_fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *value = (buffer[1] << 8) | buffer[0];

    return 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the VEML7700
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure the VEML7700 (example configuration)
    uint8_t config_data[2];
    config_data[0] = VEML7700_CONFIG; // Configuration register address
    config_data[1] = 0x00; // Example: Integration time = 100ms, Gain = 1/8

    if (write(i2c_fd, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print data
    while (1) {
        uint16_t als_data;

        if (read_veml7700(&als_data) == 0) {
            printf("ALS Data: %u\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data.\n");
        }

        sleep(0.5);
    }

    // The program will exit via the signal handler
    return 0;
}

#include <stdio.h>
