#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B9600
#define TIMEOUT_MS 100

static volatile int keep_running = 1;
static int uart_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 0.1 seconds (1 decisecond)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0;
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the string
        return (int)bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    char buffer[256];
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    printf("Reading from UART. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    close(uart_fd);
    printf("UART closed. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define MAX_DISTANCE 400     // cm
#define TIMEOUT_US 200000    // 200ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulse() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 100 to get cm
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = measurePulse();

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);

            if (distance > 0 && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout or error reading sensor\n");
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

