#include <string.h>

#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

int main() {
    int file;
    char filename[20];
    int16_t x, y, z;
    uint8_t data[6];

    strcpy(filename, "/dev/i2c-1");
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Wake up the ADXL345
    uint8_t power_ctl_value = 0x08; // Set bit 3 to 1
    uint8_t buf[2];
    buf[0] = POWER_CTL;
    buf[1] = power_ctl_value;
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to POWER_CTL register");
        close(file);
        return 1;
    }

    // Set data format to +/- 2g range and full resolution
    uint8_t data_format_value = 0x0B; // 0x0B for +/-2g and full resolution
    buf[0] = DATA_FORMAT;
    buf[1] = data_format_value;
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to DATA_FORMAT register");
        close(file);
        return 1;
    }

    // Read accelerometer data
    buf[0] = DATAX0; // Start reading from DATAX0
    if (write(file, buf, 1) != 1) {
        perror("Failed to write to DATAX0 register");
        close(file);
        return 1;
    }

    if (read(file, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        close(file);
        return 1;
    }

    x = (int16_t)((data[1] << 8) | data[0]);
    y = (int16_t)((data[3] << 8) | data[2]);
    z = (int16_t)((data[5] << 8) | data[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    close(file);
    return 0;
}

