    gpio27_line = gpiod_chip_get_line(chip, GPIO_27);

    if (!gpio4_line || !gpio17_line || !gpio27_line) {
        fprintf(stderr, "Error getting GPIO line(s)\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio4_line, &config, 0) < 0 ||
        gpiod_line_request(gpio17_line, &config, 0) < 0 ||
        gpiod_line_request(gpio27_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line(s) for output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        if (set_gpio_state(gpio4_line, 1) < 0) return 1;
        if (set_gpio_state(gpio17_line, 0) < 0) return 1;
        if (set_gpio_state(gpio27_line, 1) < 0) return 1;

        // Print GPIO states
        printf("GPIO %d: 1, GPIO %d: 0, GPIO %d: 1\n", GPIO_4, GPIO_17, GPIO_27);

        // Wait for 0.5 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO states
        if (set_gpio_state(gpio4_line, 0) < 0) return 1;
        if (set_gpio_state(gpio17_line, 1) < 0) return 1;
        if (set_gpio_state(gpio27_line, 0) < 0) return 1;

        // Print GPIO states
        printf("GPIO %d: 0, GPIO %d: 1, GPIO %d: 0\n", GPIO_4, GPIO_17, GPIO_27);

        // Wait for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int duty_cycle = 0;
    int increment = 10;

    while (!terminate) {
        // Set PWM duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the current duty cycle
        printf("Duty Cycle: %d\n", duty_cycle);

        // Update duty cycle
        duty_cycle += increment;

        // Reverse direction if at the extremes
        if (duty_cycle >= PWM_RANGE) {
            increment = -10;
        } else if (duty_cycle <= 0) {
            increment = 10;
        }

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Release GPIO 18
    gpioSetMode(PWM_GPIO, PI_INPUT); // Set back to input (safer)

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

