// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define STATE_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define timeout for echo pulse (in microseconds)
#define TIMEOUT 30000 // 30ms

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line, *state_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int setup_gpio();
void trigger_pulse();
long measure_pulse_width();
void set_state(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int value;
} gpio_line_t;

// Function to set the state of a GPIO line
void set_gpio_line(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

// Function to read the value of a GPIO line
int get_gpio_line_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO line value");
        cleanup();
        exit(EXIT_FAILURE);
    }
    return value;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the echo pulse width
        long pulse_width = measure_pulse_width();

        // Calculate distance (in cm) - speed of sound: 343 m/s
        // distance = (pulse_width * 0.000001) * 34300 / 2;
        // For simplicity, we'll just print the pulse width
        printf("Pulse width: %ld us\n", pulse_width);

        // Set the state (0 or 1)
        set_state(1); // Example: Set state to 1

        // Wait for a short period
        usleep(500000); // 0.5 seconds
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

// Function to set up GPIO lines
int setup_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    state_line = gpiod_chip_get_line(chip, STATE_PIN);

    if (!trigger_line || !echo_line || !state_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "echo") < 0 ||
        gpiod_line_request_output(state_line, "state", 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to send a trigger pulse
void trigger_pulse() {
    // Set trigger pin high
    set_gpio_line(trigger_line, 1);
    usleep(10); // 10 us
    // Set trigger pin low
    set_gpio_line(trigger_line, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width;

    // Wait for echo pin to go high (with timeout)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (get_gpio_line_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for echo high.\n");
            return -1; // Timeout
        }
    }

    // Record start time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo pin to go low (with timeout)
    while (get_gpio_line_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for echo low.\n");
            return -1; // Timeout
        }
    }

    // Record end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Function to set the state of the state pin
void set_state(int state) {
    if (gpiod_line_set_value(state_line, state) < 0) {
        perror("Error setting state pin value");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release GPIO resources
void cleanup() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (state_line) {
        gpiod_line_release(state_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

