#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
long pulse_width();
float calculate_distance(long pulse_width_us);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for the echo pin to go high (start of pulse)
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (timeout++ > TIMEOUT_US) return -1; // Timeout
    }

    // Wait for the echo pin to go low (end of pulse)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (timeout++ > TIMEOUT_US) return -1; // Timeout
    }

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width_us) {
    if (pulse_width_us < 0) return -1.0; // Indicate error
    return (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_pulse();
        long pulse_width = pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance > 0 && distance < 400) { // Validate distance
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout or error reading pulse width\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

