#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable register values
#define TCS34725_ENABLE_AIEN 0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN 0x08   // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN 0x02   // ALS Enable
#define TCS34725_ENABLE_PON 0x01   // Power on

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an I2C register
int i2c_read_word(int fd, unsigned char reg, unsigned short *value) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (data[1] << 8) | data[0];
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable power and ALS
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000); // Wait for power-on
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;

    // Set integration time (ATIME) - Adjust as needed
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xEB) < 0) return -1; // 101ms integration time

    // Set gain (AGAIN) - Adjust as needed
    if (i2c_write_byte(fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, 0x01) < 0) return -1; // Gain = 4x

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    unsigned short clear, red, green, blue;
    unsigned char enable_reg;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed. Check if the device is present.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read color data
        if (i2c_read_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_CDATA, &clear) < 0) continue;
        if (i2c_read_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_RDATA, &red) < 0) continue;
        if (i2c_read_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_GDATA, &green) < 0) continue;
        if (i2c_read_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_BDATA, &blue) < 0) continue;

        // Print the color data
        printf("C: %5d R: %5d G: %5d B: %5d\n", clear, red, green, blue);

        // Wait for 0.5 seconds
        usleep(500000); // 500ms
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

