#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_24 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line24;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line24) {
        gpiod_line_release(line24);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return 1;
    }

    line24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line24) {
        perror("Error getting GPIO line 24");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_program";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line17, &config, 0) < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(line24, &config, 0) < 0) {
        perror("Error requesting GPIO line 24 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial output values
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("Error setting GPIO line 17 value");
        gpiod_line_release(line17);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_value(line24, 0) < 0) {
        perror("Error setting GPIO line 24 value");
        gpiod_line_release(line17);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print initial state
    printf("GPIO 17: %d, GPIO 24: %d\n", gpiod_line_get_value(line17), gpiod_line_get_value(line24));

    // Toggle GPIO 17 every 1 second
    for (int i = 0; i < 5; ++i) {
        if (gpiod_line_set_value(line17, !gpiod_line_get_value(line17)) < 0) {
            perror("Error toggling GPIO line 17");
            gpiod_line_release(line17);
            gpiod_line_release(line24);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO 17: %d, GPIO 24: %d\n", gpiod_line_get_value(line17), gpiod_line_get_value(line24));
        sleep(1);
    }

    // Clean up and exit
    gpiod_line_release(line17);
    gpiod_line_release(line24);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to output
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(GPIO_2, 1000);
    gpioSetPWMfrequency(GPIO_3, 1000);
    gpioSetPWMfrequency(GPIO_18, 1000);

    // Set PWM range to 1000
    gpioSetPWMrange(GPIO_2, 1000);
    gpioSetPWMrange(GPIO_3, 1000);
    gpioSetPWMrange(GPIO_18, 1000);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        // Set PWM duty cycle to 50% for all GPIOs
        gpioPWM(GPIO_2, 500);
        gpioPWM(GPIO_3, 500);
        gpioPWM(GPIO_18, 500);

        printf("GPIO 2: %d, GPIO 3: %d, GPIO 18: %d\n", gpioRead(GPIO_2), gpioRead(GPIO_3), gpioRead(GPIO_18));

        gpioDelay(5000000); // 5 seconds

        // Stop PWM output
        gpioPWM(GPIO_2, 0);
        gpioPWM(GPIO_3, 0);
        gpioPWM(GPIO_18, 0);

        printf("GPIO 2: %d, GPIO 3: %d, GPIO 18: %d\n", gpioRead(GPIO_2), gpioRead(GPIO_3), gpioRead(GPIO_18));

        gpioDelay(5000000); // 5 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

