#define BAUD_RATE B9600
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read doesn't block
    tty.c_cc[VTIME] = 5;                             // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("UART setup successful. Reading from %s at %d baud.\n", UART_DEVICE, BAUD_RATE);

    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while (program_running) {
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, sleep for 0.1 seconds
                struct timespec ts = {0, 100000000}; // 0.1 seconds
                nanosleep(&ts, NULL);
                continue;
            } else {
                perror("Error reading from UART");
                break;
            }
        } else {
            // Read returned 0, which means the device closed the connection.
            printf("Device disconnected.\n");
            break;
        }

        struct timespec ts = {0, 100000000}; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

