#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define GROUND_PIN 24

// Define constants
#define MAX_PULSE_DURATION 30000 // Maximum pulse duration in microseconds (30ms)
#define TIMEOUT 25000            // Timeout in microseconds (25ms)

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *trigger_line, *echo_line, *ground_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int setup_gpio();
void trigger_pulse();
long measure_pulse();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Setup GPIO lines
int setup_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    ground_line = gpiod_chip_get_line(chip, GROUND_PIN);

    if (!trigger_line || !echo_line || !ground_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        cleanup_gpio();
        return -1;
    }

    if (gpiod_line_request_output(ground_line, "ground", 0) < 0) {
        perror("Error requesting ground line as output");
        cleanup_gpio();
        return -1;
    }

    // Set ground pin to low initially
    gpiod_line_set_value(ground_line, 0);

    return 0;
}

// Generate a trigger pulse
void trigger_pulse() {
    // Set trigger pin high
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10us pulse

    // Set trigger pin low
    gpiod_line_set_value(trigger_line, 0);
}

// Measure the echo pulse duration
long measure_pulse() {
    struct timespec start, end;
    long duration;

    // Wait for echo pin to go high (with timeout)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration > TIMEOUT) {
            fprintf(stderr, "Timeout waiting for echo high.\n");
            return -1; // Timeout
        }
    }

    // Record start time
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for echo pin to go low (with timeout)
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration > MAX_PULSE_DURATION) {
            fprintf(stderr, "Timeout waiting for echo low.\n");
            return -1; // Timeout
        }
    }

    // Record end time
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse duration
    duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return duration;
}

// Cleanup GPIO lines and chip
void cleanup_gpio() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (ground_line) {
        gpiod_line_release(ground_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse duration
        long pulse_duration = measure_pulse();

        if (pulse_duration > 0) {
            // Calculate distance (speed of sound: 343 m/s or 0.0343 cm/us)
            // Distance = (pulse_duration * 0.0343) / 2
            float distance = (pulse_duration * 0.0343) / 2.0;

            // Print the distance
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error measuring pulse.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

