        return 1;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    while (!terminate) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error getting GPIO line value");
            break;
        }

        printf("GPIO %d state: %d\n", GPIO_PIN, value);

        ret = gpiod_line_set_value(line, !value);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            break;
        }

        usleep(600000); // 0.6 seconds
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}
